/* Fifth-round visual prototype. Rates, balances and repayment schedules are fictional examples.
   These helpers drive UI states only; they are not the production financial engine. */
const currencyLabels={JPY:['日元','日本円'],CNY:['人民币','人民元'],USD:['美元','米ドル']};
const exampleRates={JPY:1,CNY:20,USD:150};
const bookCurrency=()=>book().baseCurrency||'JPY';
const accountCurrency=id=>account(id)?.currency||'JPY';
function demoConvert(n,from,to){const amount=Number(n||0)*exampleRates[from]/exampleRates[to];return to==='JPY'?Math.round(amount):Math.round(amount*100)/100;}
const baseMoney=n=>moneyIn(n,bookCurrency());
const accountMoney=(a,n)=>moneyIn(n,a?.currency||'JPY');
const currencyOptions=()=>Object.entries(currencyLabels).map(([id,words])=>[id,`${id} · ${t(...words)}`]);
const budgetRecords=(month=CURRENT_MONTH)=>expenses(month).filter(r=>!book().activities.find(a=>a.id===r.activity)?.excludeMonthly);
function recordMainMoney(r){return moneyIn(r.accountAmount??r.amount,r.currency||accountCurrency(r.account));}
function recordOriginalMoney(r){return r.originalCurrency&&r.originalCurrency!==(r.currency||accountCurrency(r.account))?`<p class="record-original-money">${t('原币','原通貨')} ${moneyIn(r.originalAmount,r.originalCurrency)} · ${r.settlementState==='pending'?t('换算待确认','換算未確定'):t('入账已确认','計上確定')}</p>`:'';}
function initExperience(){
 books.forEach(b=>{b.baseCurrency||='JPY';b.accounts.forEach(a=>a.currency||='JPY');b.analysisPrefs??=null;b.activities.forEach(a=>{a.excludeMonthly??=false;a.holdEnabled??=false;a.holdAmount??=0;a.categoryBudgets||={};});});
 const b=dailySeed;b.accounts.push({id:'bank-cn',name:'人民币生活账户',ja:'人民元生活口座',type:'bank',currency:'CNY',balance:6800},{id:'bank-us',name:'美元账户',ja:'米ドル口座',type:'bank',currency:'USD',balance:320},{id:'loan-cn',name:'国内借款 · 我的分期',ja:'人民元ローン・分割',type:'loan',currency:'CNY',balance:18000,next:8500,date:'2026-10-25',bank:'bank-cn',loanMode:'fixed',confirmed:true,rules:null,manualPlan:[{month:'2026.10',principal:8000,fee:500,pay:8500,left:10000},{month:'2026.11',principal:5000,fee:300,pay:5300,left:5000},{month:'2026.12',principal:5000,fee:200,pay:5200,left:0}]});
 const kyoto=b.activities.find(a=>a.id==='kyoto');kyoto.excludeMonthly=true;kyoto.friends=['kobayashi','chen'];kyoto.categoryBudgets={food:10000,shopping:5000,transport:10000};
 b.treats=[{id:'kyoto-me',record:'f5',date:'2026-10-11',payer:'me',amount:6200,alloc:{me:2066,kobayashi:2067,chen:2067},merchant:'京都のごはん',activity:'kyoto'},{id:'kyoto-other',date:'2026-10-11',payer:'kobayashi',amount:9400,alloc:{me:4700,kobayashi:4700},merchant:'京都の夕食',activity:'kyoto'}];
 b.records.push({id:'fx1',type:'expense',date:'2026-10-08',amount:15000,accountAmount:15000,currency:'JPY',originalCurrency:'USD',originalAmount:100,settlementState:'pending',category:'shopping',account:'pp',merchant:'BOOKS & COFFEE ONLINE',payment:'once',activity:'',note:'外币购买 · 预计换算示例'});
}
initExperience();
accountOptions=(filter=()=>true)=>book().accounts.filter(filter).map(a=>[a.id,`${label(a)} · ${a.currency||'JPY'}`]);
const experienceArt={
 magazine:`<svg viewBox="0 0 160 140" class="experience-art" aria-hidden="true"><path d="M31 103V29h82v74ZM40 45h43m-43 12h63M40 70h36m-36 12h63M65 112h82M93 94c-3-32 15-58 47-70M105 76c-21-2-22-14-11-20m17 5c21 0 31-8 28-21M95 103l15-35"/><ellipse cx="69" cy="118" rx="39" ry="6" opacity=".2"/></svg>`,
 journal:`<svg viewBox="0 0 160 140" class="experience-art" aria-hidden="true"><path d="m25 30 95-6 5 91-92 8Z M45 38l-2 64M57 46l49-4m-49 19 39-3m-38 19 49-3m-47 19 30-3M19 32l3 86M116 105l16-70 10 3-15 69-10 10Z M134 34l2-8 10 3-2 8"/><path d="m66 108 4 4 10-13"/></svg>`,
 objects:`<svg viewBox="0 0 160 140" class="experience-art" aria-hidden="true"><ellipse cx="80" cy="115" rx="66" ry="10" opacity=".14"/><path d="M27 71h90l-5 39H34ZM42 70V51h62v20M66 56l6-28 38 8-7 27"/><path d="M77 39l23 5m-25 4 17 4"/><circle cx="126" cy="91" r="14"/><circle cx="126" cy="91" r="9"/><ellipse cx="52" cy="94" rx="12" ry="5"/><path d="M40 94v7c1 7 24 7 24 0v-7"/></svg>`
};
function experienceLead(kind,title,sub,kicker,amount='',aside=''){
 const theme=themeName();
 if(theme==='magazine')return `<header class="exp-lead editorial-${kind}"><div class="exp-edition"><span>${kicker}</span><span>YOHAKU / 05</span></div><div class="editorial-lead-columns"><div><h1>${title}</h1><p>${sub}</p>${amount?`<div class="exp-lead-amount">${amount}</div>`:''}</div><aside>${experienceArt.magazine}${aside}</aside></div></header>`;
 if(theme==='journal')return `<header class="exp-lead notebook-${kind}"><span class="exp-tape" aria-hidden="true"></span><div class="exp-hand-caption">✳ ${kicker}</div><h1>${title}</h1><p>${sub}</p>${amount?`<div class="exp-hand-answer">${amount}<i>↗</i></div>`:''}<div class="exp-sketch">${experienceArt.journal}</div>${aside?`<div class="exp-margin-note">${aside}</div>`:''}</header>`;
 return `<header class="exp-lead objects-${kind}"><span class="exp-object-label">${kicker}</span><div class="exp-object-copy"><h1>${title}</h1><p>${sub}</p>${amount?`<div class="exp-object-amount">${amount}</div>`:''}</div><div class="exp-object-art">${experienceArt.objects}</div>${aside?`<div class="exp-object-tag">${aside}</div>`:''}</header>`;
}
function expToggle(name,title,sub,checked=false){return `<label class="exp-toggle"><span><strong>${title}</strong><small>${sub}</small></span><input type="checkbox" name="${name}" ${checked?'checked':''}><i aria-hidden="true"></i></label>`;}
function entryCurrencyFields(s){const f=s.fields,currency=accountCurrency(f.account),original=f.originalCurrency||currency,foreign=original!==currency;return `<div class="entry-currency-block">${field('amount',`${f.settlementState==='pending'?t('预计入账金额','計上見込額'):t('账户实际入账金额','口座の実際の計上額')} · ${currency}`,'number',f.amount,`min="${currency==='JPY'?1:.01}" step="${currency==='JPY'?1:.01}" required inputmode="decimal" class="amount-input"`)}${f.type==='repayment'&&accountCurrency(f.to)!==currency?field('targetPrincipal',`${t('实际归还本金','実際の元金返済額')} · ${accountCurrency(f.to)}`,'number',f.targetPrincipal??'','min="0" step="any" required'):''}${['expense','income','refund'].includes(f.type)?`<div class="original-currency-control">${selectField('originalCurrency',t('消费 / 收付原币','取引の原通貨'),currencyOptions(),original)}${foreign?field('originalAmount',`${t('原币金额','原通貨額')} · ${original}`,'number',f.originalAmount||'','min="0" step="any" inputmode="decimal"'):''}</div>${foreign?`<div class="currency-entry-note"><span>${t('两种金额，仍是一笔记录','二つの金額、同じ一件')}</span><p>${t('保留原币价格；预算按入账金额折算。参考汇率不覆盖你填写的实际金额。','原通貨の価格を保持。予算は計上額から換算。参考レートは実額を上書きしません。')}</p>${act('foreign-estimate',t('按参考汇率估算入账','参考レートで計上額を見積もる'),'type="button"','fx-estimate-button')}${selectField('settlementState',t('入账金额状态','計上額の状態'),[['confirmed',t('已确认实际金额','実額確認済')],['pending',t('预计换算 · 待账单确认','換算見込み・明細確認待ち')]],f.settlementState||'pending')}</div>`:''}`:''}<div class="entry-base-caption">${t('本位币参考','基準通貨の参考')} ${baseMoney(demoConvert(Number(f.amount),currency,bookCurrency()))} ${currency!==bookCurrency()?t('· 示例汇率估值','・デモレート評価'):''}</div></div>`;}
transaction=r=>{const type={expense:t('支出','支出'),income:t('收入','収入'),refund:t('退款','返金'),transfer:t('转账','振替'),repayment:t('还款','返済'),borrowing:t('借入','借入')}[r.type],a=account(r.account),foreign=r.originalCurrency&&r.originalCurrency!==(r.currency||a?.currency);return `<button class="transaction" data-action="transaction" data-id="${r.id}"><span class="tx-icon">${icon(category(r.category)?.icon||'wallet')}</span><span class="tx-info"><strong>${esc(r.merchant||type)}</strong><small>${shortDate(r.date)} · ${r.type==='expense'?catLabel(r.category):type}${r.activity?`<span class="tag">${t('活动','シーン')}</span>`:''}${r.settlementState==='pending'?`<span class="tag">${t('换算待确认','換算未確定')}</span>`:''}</small>${foreign?`<span class="tx-original">${moneyIn(r.originalAmount,r.originalCurrency)}</span>`:''}</span><span class="tx-amount">${['income','refund'].includes(r.type)?'+':'−'}${recordMainMoney(r)}<small>${esc(label(a))}</small></span></button>`;};
function heroMoney(n){const currency=bookCurrency(),digits=Number(n||0).toLocaleString('ja-JP',{minimumFractionDigits:currency==='JPY'?0:2,maximumFractionDigits:currency==='JPY'?0:2});return `<small class="money-prefix">${currency==='JPY'?'¥':currency}</small><span class="money-value">${digits}</span>`;}
function homeNumbers(month=CURRENT_MONTH){const b=book(),all=sum(expenses(month),expenseNet),used=spending(month),independent=all-used,held=month===CURRENT_MONTH?reserve():0,cash=sum(b.accounts.filter(a=>!isDebt(a)),a=>demoConvert(a.balance,a.currency,bookCurrency()));return {all,used,independent,held,left:b.budget-used,free:b.budget-used-held,cash,pending:budgetRecords(month).filter(r=>r.settlementState==='pending').length};}
screens.home=()=>{const n=homeNumbers(),b=book(),theme=themeName(),loan=b.accounts.find(a=>a.type==='loan'&&a.currency==='CNY'),loanBank=loan?account(loan.bank):null,gap=loan&&loanBank?Math.max(0,loan.next-demoConvert(loanBank.balance,loanBank.currency,loan.currency)):0;const main=theme==='magazine'?`<section class="exp-home-cover editorial-home-cover"><span class="eyebrow">THE MONTHLY ALLOWANCE</span><h1>${t('日常，也有余地。','日々に、余白を。')}</h1><div class="exp-home-columns"><div><span>${t('本月预算内还能花','今月の予算内で使える')}</span><strong class="home-money ${bookCurrency()==='JPY'?'':'foreign-money'}">${heroMoney(n.left)}</strong></div><aside>${experienceArt.magazine}<span>${t('预留安排后','予定分を確保した後')}<b class="home-aside-money">${heroMoney(n.free)}</b></span></aside></div><footer><span>${t('预算','予算')} ${baseMoney(b.budget)}</span><span>${t('预算内已花','予算内の支出')} ${baseMoney(n.used)}</span></footer></section>`:theme==='journal'?`<section class="exp-home-cover notebook-home-cover"><span class="exp-tape"></span><span>${t('十月的生活小算式','10月の暮らしの計算')}</span><h1>${t('今天，也慢慢记。','今日も、ゆっくり記そう。')}</h1><div class="home-hand-equation"><span>${baseMoney(b.budget)}</span><i>−</i><span>${baseMoney(n.used)}</span><i>＝</i></div><strong class="home-money ${bookCurrency()==='JPY'?'':'foreign-money'}">${heroMoney(n.left)}</strong><div class="home-hand-caption">${t('本月预算内还能花','今月の予算内で使える')} ↗</div><footer>${t('再留出计划支出','予定支出も確保して')} ${baseMoney(n.held)}<b>${t('自由可花','自由に使える')} ${baseMoney(n.free)}</b></footer></section>`:`<section class="exp-home-cover objects-home-cover"><span class="money-pouch-cord" aria-hidden="true"></span><span>${t('这个月的日常钱袋','今月の日々のお財布')}</span><h1>${t('留一点，给明天。','明日に、少し残そう。')}</h1><strong class="home-money ${bookCurrency()==='JPY'?'':'foreign-money'}">${heroMoney(n.left)}</strong><small>${t('本月预算内还能花','今月の予算内で使える')}</small><div class="pouch-mini-pockets"><span>${t('待付安排先留好','予定支払を確保')}<b>${baseMoney(n.held)}</b></span><span>${t('自由可花','自由に使える')}<b>${baseMoney(n.free)}</b></span></div></section>`;
 return `${b.activeActivity?`<div class="mode-banner"><span>${t('活动记账中','シーン記録中')} · ${esc(label(b.activities.find(a=>a.id===b.activeActivity)))}</span>${act('exit-activity',t('退出','終了'))}</div>`:''}${b.budget?main:experienceLead('empty-home',t('从第一笔，开始。','最初の一筆から。'),t('先设置月预算，也可以先添加账户。','月予算の設定、または口座追加から。'),'A FRESH START')}${n.pending?`<div class="budget-estimate-note">${t(`预算暂含 ${n.pending} 笔预计换算，账单确认后更新。`,`予算に仮換算${n.pending}件を含む。明細確認後に更新。`)}</div>`:''}${!b.budget?act('edit-budget',t('设置月预算','月予算を設定'),'','full-button'):''}<div class="home-spend-context"><div><span>${t('本月全部净消费','今月の純支出全体')}</span><b>${baseMoney(n.all)}</b></div><div><span>${t('其中独立活动支出','うち独立シーンの支出')}</span><b>${baseMoney(n.independent)}</b></div></div>${section(t('钱够不够，还要看账户。','支払いは、口座残高も。'),'REAL FUNDS')}<div class="home-cash-note"><span>${t('资金账户参考合计','資金口座の参考合計')}</span><strong>${baseMoney(n.cash)}</strong><small>${t('多币种按示例汇率估值，信用额度不计入。','複数通貨はデモレート評価。利用枠は含みません。')}</small></div>${gap>0?`<div class="exp-risk-card"><span class="risk-date">10 / 25</span><div><strong>${t('人民币还款，先准备到账。','人民元の返済、入金準備を。')}</strong><p>${t(`扣款账户差 ${accountMoney(loan,gap)}，其他账户资金需先转入或兑换。`,`引落口座は${accountMoney(loan,gap)}不足。他の資金は振替・両替が必要。`)}</p><small>${t(`按示例参考汇率约需 ${moneyIn(demoConvert(gap,loan.currency,'JPY'),'JPY')}，未知费用另计。`,`デモレートで約${moneyIn(demoConvert(gap,loan.currency,'JPY'),'JPY')}。未確定手数料は別。`)}</small></div>${act('exchange-open',t('安排换汇','両替を準備'),'data-from="bank-s" data-to="bank-cn"','inline-button')}</div>`:''}${section(t('接下来的付款','これからのお支払い'),'UP NEXT','calendar',t('日历','カレンダー'))}<div class="exp-due-list">${b.accounts.filter(isDebt).sort((a,c)=>a.date.localeCompare(c.date)).slice(0,3).map(a=>`<button data-page="${a.type==='loan'?'loan':'credit'}" data-id="${a.id}" class="exp-due"><span>${shortDate(a.date)}</span><div><strong>${esc(label(a))}</strong><small>${esc(label(account(a.bank)))} · ${a.confirmed?t('已确认','確認済'):t('预计','見込み')}</small></div><b>${accountMoney(a,a.next)}</b></button>`).join('')||empty(t('还没有还款安排','支払予定はありません'))}</div>${section(t('最近的几笔','最近の記録'),'DAILY NOTES','ledger',t('全部流水','すべて'))}<div class="transaction-list">${b.records.filter(r=>r.type==='expense').slice().sort((a,c)=>c.date.localeCompare(a.date)).slice(0,3).map(transaction).join('')||empty(t('分类由你创建，记第一笔就开始。','カテゴリは自分で作成。最初の一筆から。'),'entry',t('记一笔','記録'))}</div><div class="exp-home-shortcuts">${pageButton('analysis',t('按自己的重点看分析','自分の視点で分析'))}${pageButton('life',t('活动与小票','シーンとレシート'))}</div>`;
};
budgetView=()=>{const n=homeNumbers(analysisMonth);return `${experienceLead('budget',t('日常与活动，分开留。','日常とシーン、分けて残す。'),t('月预算内支出与独立活动支出分开表达。','月予算の支出と独立シーン支出を区別。'),'THE MONTHLY BALANCE',baseMoney(n.left),t('本月预算余额','今月の予算残額'))}<div class="exp-budget-equation">${rows([[t('月预算','月予算'),baseMoney(book().budget)],[t('预算内已花','予算内支出'),`− ${baseMoney(n.used)}`],[t('预算内待付预留','予算内予定の確保'),`− ${baseMoney(n.held)}`],[t('预留后还能花','確保後に使える'),`<b>${baseMoney(n.free)}</b>`]])}</div>${n.pending?`<div class="budget-estimate-note">${t(`含 ${n.pending} 笔预计换算，当前余量尚待确认。`,`仮換算${n.pending}件を含む。残額は未確定。`)}</div>`:''}${act('edit-budget',t('调整月预算','月予算を変更'),'','full-button')}<div class="independent-budget-note"><strong>${t('独立活动另计','独立シーンは別枠')}</strong><span>${baseMoney(n.independent)}</span><p>${t('这部分仍是真实消费，但不占用月总预算或月分类预算。','実際の支出ですが、月全体・月カテゴリの予算に含めません。')}</p></div>${section(t('月分类预算','月のカテゴリ予算'),'CATEGORY LIMITS')}<p class="hierarchy-form-note">${t('一级预算含二级与未细分消费；二级预算是其中专项，不重复相加。','親予算は子と内訳未分類を含む。子予算は内訳で、二重加算しません。')}</p><div class="theme-budget-list">${orderedCategories().map(c=>{const used=sum(budgetRecords(analysisMonth).filter(r=>categoryContains(c.id,r.category)),expenseNet);return `<button class="theme-budget-item" data-action="category-budget" data-id="${c.id}"><span class="budget-item-icon">${icon(c.icon)}</span><strong>${c.parent?"↳ ":""}${t(...c.name)}</strong><span class="budget-item-left">${baseMoney(c.budget-used)}</span><small>${t('预算内已花 / 预算','予算内支出 / 予算')} ${baseMoney(used)} / ${baseMoney(c.budget)}</small>${budgetTrack(used,c.budget)}</button>`;}).join('')||empty(t('还没有创建分类','カテゴリはまだありません'),'new-category',t('创建分类','カテゴリを作成'))}</div>`;};
let setupState={step:0,name:'',base:'JPY',budget:'',date:TODAY,accounts:[]},accountDraft=null,analysisDraft=[],analysisPreview=false;
function setupSteps(){return `<div class="setup-steps">${[t('账本','帳簿'),t('资金','資金'),t('欠款','借入'),t('检查','確認')].map((title,i)=>`<span class="${setupState.step===i+1?'current':setupState.step>i+1?'done':''}"><b>${String(i+1).padStart(2,'0')}</b><small>${title}</small></span>`).join('')}</div>`;}
screens.onboarding=()=>{
 const s=setupState;
 if(!s.step)return `${experienceLead('welcome',t('从今天开始，留一点余量。','今日から、少し余白を。'),t('不用补齐所有过去。从现有余额和欠款开始，慢慢记下日常。','過去の全記録は不要。今の残高と借入から、日々を少しずつ。'),'YOUR FIRST PAGE',t('你好，余量。','こんにちは、ヨハク。'),t('分类从空白开始','カテゴリは空白から'))}<div class="setup-intro-list">${[[t('一本独立的账本','独立した帳簿'),t('账户、预算、活动和资料各自独立。','口座・予算・シーン・資料を独立管理。')],[t('期初不是新的消费','期首残高は新しい支出ではない'),t('现有余额、欠款和已确认账单分别填写。','今の残高・借入・確定明細を分けて入力。')],[t('复杂规则可以稍后补齐','計算条件は後からでも'),t('没有规则时，只展示已知安排，不假装能准确预测。','条件未設定なら既知の予定のみ。正確な予測を装いません。')]].map(([title,note],i)=>`<div><span>${String(i+1).padStart(2,'0')}</span><section><h3>${title}</h3><p>${note}</p></section></div>`).join('')}</div>${act('setup-start',t('开始设置我的账本','マイ帳簿を設定'),'','full-button')}<p class="exp-demo-note">${t('首次使用流程预览；现有演示账本不会被清空。','初回設定のプレビュー。既存デモ帳簿は消去しません。')}</p>`;
 const titles=[null,[t('先给日常，一个名字。','日々に、名前を。'),t('本位币用于预算和分析；账户仍可持有不同币种。','基準通貨は予算・分析用。口座は別の通貨も持てます。')],[t('现在的钱，放在哪里？','今のお金は、どこに？'),t('填入开始日期的实际余额，不当作收入。','開始日の実残高を入力。収入として計上しません。')],[t('已有的欠款，接着记。','今ある借入も、ここから。'),t('本金、已确认账单和未来计划分开，不重复计债务。','元金・確定明細・将来計画を区別。借入を重複計上しません。')],[t('检查一下，就可以开始。','確認して、はじめよう。'),t('分类由你自己创建，分析重点也由你选择。','カテゴリも、分析の視点も、自分で選択。')]];
 const title=titles[s.step];let content='';
 if(s.step===1)content=`<form id="setup-book-form">${field('name',t('账本名称','帳簿名'),'text',s.name,'required maxlength="30"')}${selectField('base',t('统计本位币','集計の基準通貨'),currencyOptions(),s.base)}${field('budget',`${t('月预算 / 可稍后设置','月予算・後から設定可')} · ${s.base}`,'number',s.budget,'min="0" step="any" inputmode="decimal"')}${field('date',t('开始记账日期','記録の開始日'),'date',s.date,'required')}<div class="setup-note">${t('新账本没有预建分类，也不复制其他账本的账户和记录。','新しい帳簿はカテゴリ未作成。他の口座・記録はコピーしません。')}</div><button class="full-button" type="submit">${t('下一步：资金账户','次へ：資金口座')}</button></form>`;
 if(s.step===2||s.step===3){const debt=s.step===3,as=s.accounts.filter(a=>isDebt(a)===debt);content=`<div class="setup-account-list">${as.map(a=>setupAccountCard(a)).join('')||empty(debt?t('可以先填下次已确认应还，再补本金和计划。','次回確定額から入力し、元金・計画は後で補足。'):t('从现金或常用银行账户开始。外币账户也可以加入。','現金やよく使う銀行から。外貨口座も追加できます。'))}</div>${act('setup-add-account',`＋ ${debt?t('添加已有信用卡 / 借款','カード・借入を追加'):t('添加资金账户','資金口座を追加')}`,`data-debt="${debt}"`,'outline-button')}${act('setup-sample',t('用一组虚构数据体验','架空データで試す'),`data-debt="${debt}"`,'text-link')}<div class="setup-note">${debt?t('已确认账单是期初债务的还款安排，不会再叠加一份欠款。','確定明細は期首借入の返済予定。借入額に重ねません。'):t('每个账户保留原币余额。只有汇总展示才做参考换算。','口座残高は元通貨を保持。集計表示だけ参考換算。')}</div>${act('setup-next',as.length?t('保存这一页，继续','このページを保存して次へ'):t('先跳过，稍后添加','後で追加して次へ'),'','full-button')}`;}
 if(s.step===4)content=`<div class="setup-review">${rows([[t('账本','帳簿'),esc(s.name)],[t('本位币','基準通貨'),`${s.base} · ${t(...currencyLabels[s.base])}`],[t('月预算','月予算'),s.budget?moneyIn(s.budget,s.base):t('稍后设置','後で設定')],[t('开始日期','開始日'),s.date]])}<div class="setup-review-accounts">${s.accounts.map(a=>setupAccountCard(a)).join('')||`<p class="muted">${t('账户尚未添加，可进入后继续。','口座未作成。開始後に追加できます。')}</p>`}</div><div class="setup-next-pages"><span>□ ${t('分类：尚未创建','カテゴリ：未作成')}</span><span>□ ${t('分析重点：等待你选择','分析の視点：選択待ち')}</span><span>□ ${t('金融规则：按账户逐步补齐','金融条件：口座ごとに補足')}</span></div></div>${act('setup-finish',t('完成，进入我的空白账本','完了・空白のマイ帳簿へ'),'','full-button')}`;
 return `${setupSteps()}${experienceLead('setup',title[0],title[1],`FIRST STEPS / 0${s.step}`)}${content}${act('setup-back',t('上一步','前へ'),'','setup-back-link')}`;
};
function setupAccountCard(a){return `<button class="setup-account" data-action="setup-edit-account" data-id="${a.id}"><span class="setup-account-currency">${a.currency}</span><div><strong>${esc(label(a))}</strong><small>${isDebt(a)?t('期初未还本金','期首未返済元金'):t('期初资金余额','期首残高')} · ${setupState.date}</small></div><b>${accountMoney(a,a.balance)}</b><span>↗</span></button>`;}
function beginAccountEditor(id='',setup=false,debt=false){const a=(setup?setupState.accounts:book().accounts).find(a=>a.id===id);accountDraft={setup,id,values:{...(a||{}),type:a?.type||(debt?'credit':'bank'),currency:a?.currency||(setup?setupState.base:bookCurrency()),snapshotDate:a?.snapshotDate||setupState.date||TODAY,loanMode:a?.loanMode||'fixed'}};renderAccountEditor();}
accountForm=(id='')=>beginAccountEditor(id);
function stashAccount(){const f=document.getElementById('experience-account-form');if(f)accountDraft.values={...accountDraft.values,...Object.fromEntries(new FormData(f))};}
function renderAccountEditor(){const d=accountDraft,a=d.values,debt=isDebt(a),loan=a.type==='loan';openSheet(t(d.id?'编辑账户与期初信息':'添加账户与期初信息',d.id?'口座・期首情報を編集':'口座・期首情報を追加'),`<form id="experience-account-form"><div class="account-setup-label">${d.setup?t('首次设置 · 不计收入或消费','初回設定・収入と支出に含めません'):t('账户币种决定余额与实际入账金额','口座通貨が残高と計上額の基準')}</div>${selectField('type',t('账户类型','口座の種類'),[['cash',t('现金','現金')],['bank',t('银行 / 储蓄卡','銀行・デビット')],['credit',t('信用卡','クレジットカード')],['loan',t('网贷 / 借款','ローン・借入')],['ic',t('交通 IC','交通IC')]],a.type)}${field('name',t('账户名称','口座名'),'text',a.name||'','required')}${!d.setup&&d.id&&book().records.some(r=>r.account===d.id||r.to===d.id)?`<div class="account-currency-fixed"><span>${t('账户币种','口座通貨')}</span><b>${a.currency}</b><small>${t('已有流水，币种保持固定；其他币种请新建账户。','記録あり。通貨は固定。他の通貨は新口座へ。')}</small><input type="hidden" name="currency" value="${a.currency}"></div>`:selectField('currency',t('账户币种','口座通貨'),currencyOptions(),a.currency)}${field('balance',`${debt?t('期初未还本金','期首未返済元金'):t('期初实际余额','期首実残高')} · ${a.currency}`,'number',a.balance??'','min="0" step="any" required')}${field('snapshotDate',t('余额 / 欠款对应日期','残高・借入の基準日'),'date',a.snapshotDate,'required')}${loan?selectField('loanMode',t('借款模式','借入の方式'),[['fixed',t('每笔借款 · 固定还款计划','借入ごと・固定返済計画')],['revolving',t('循环额度 · 可反复借入','利用枠内・繰り返し借入')]],a.loanMode):''}${debt?`<section class="opening-debt-section"><h3>${t('先记录已确定的安排','確定している予定から')}</h3>${a.type==='credit'||a.loanMode==='revolving'?field('limit',`${t('总额度','利用枠')} · ${a.currency}`,'number',a.limit??'','min="0" step="any"'):''}${field('next',`${t('下次已确认应还总额','次回確定支払総額')} · ${a.currency}`,'number',a.next??'','min="0" step="any"')}${field('date',t('下次还款日期','次回支払日'),'date',a.date||TODAY)}${selectField('bank',t('实际扣款账户','引落口座'),[['',t('稍后设置','後で設定')],...(d.setup?setupState.accounts.filter(x=>!isDebt(x)).map(x=>[x.id,`${label(x)} · ${x.currency}`]):accountOptions(x=>!isDebt(x)))],a.bank)}<details class="entry-details"><summary>${t('已有分期 / リボ与逐月计划','既存の分割・リボ・月別計画')}</summary>${field('onceBalance',t('一次付未还本金','1回払い未返済元金'),'number',a.onceBalance||'','min="0" step="any"')}${field('splitBalance',t('分期剩余本金','分割残元金'),'number',a.splitBalance||'','min="0" step="any"')}${field('revoBalance',t('リボ剩余本金','リボ残元金'),'number',a.revoBalance||'','min="0" step="any"')}<div class="opening-plan-preview"><span>${t('也可先按平台给出的每月应还填写','会社の月別支払額から入力も可能')}</span><div><b>2026.10</b><input name="planOct" type="number" step="any" value="${esc(a.planOct||'')}" placeholder="${t('已知应还','確定支払額')}" aria-label="2026.10 ${t('应还金额','支払額')}"></div><div><b>2026.11</b><input name="planNov" type="number" step="any" value="${esc(a.planNov||'')}" placeholder="${t('已知应还','確定支払額')}" aria-label="2026.11 ${t('应还金额','支払額')}"></div><div><b>2026.12</b><input name="planDec" type="number" step="any" value="${esc(a.planDec||'')}" placeholder="${t('已知应还','確定支払額')}" aria-label="2026.12 ${t('应还金额','支払額')}"></div></div></details><div class="setup-note">${t('规则未配置：只展示手动确认的安排，利息、后续预测与额度恢复等待补齐。没有机构预设。','条件未設定：手動確定の予定のみ。利息・将来予測・枠回復は情報補足後。会社別プリセットなし。')}</div></section>`:''}<button type="submit" class="full-button">${t('保存账户信息','口座情報を保存')}</button></form>`);}
function startExchange(context={},keep=false){
 if(!keep){const r=context.edit?book().records.find(r=>r.id===context.edit):null;const from=context.from||r?.account||'bank-s',to=context.to||r?.to||'bank-cn';captureSession={context:{...context,flow:'exchange'},fields:{...(r||{}),type:'transfer',account:account(from)?from:book().accounts.find(a=>!isDebt(a))?.id,to:account(to)?to:book().accounts.filter(a=>!isDebt(a))[1]?.id,amount:context.amount??r?.accountAmount??r?.amount??30000,inAmount:r?.toAmount??1462.5,fee:r?.exchangeFee??750,feePosition:r?.feePosition||'from-included',feeCurrency:r?.feeCurrency||'JPY',date:r?.date||TODAY,arrivalDate:r?.arrivalDate||TODAY,transferState:r?.transferState||'confirmed',merchant:r?.merchant||t('日元换成人民币','円から人民元へ'),note:r?.note||''},attachments:[...(r?.attachments||[])],receipts:(r?.receipts||[]).map(g=>({...g,images:[...g.images],items:[...g.items]}))};}
 renderExchange();
}
function estimatedExchangeIn(){const f=captureSession.fields,from=accountCurrency(f.account),to=accountCurrency(f.to),fee=Number(f.fee)||0,principal=Number(f.amount)-(f.feePosition==='from-included'?demoConvert(fee,f.feeCurrency||from,from):0);return Math.max(0,demoConvert(principal,from,to)-(f.feePosition==='to-included'?demoConvert(fee,f.feeCurrency||to,to):0));}
function exchangeMath(){const f=captureSession.fields,from=accountCurrency(f.account),to=accountCurrency(f.to),out=Number(f.amount)||0,incoming=Number(f.inAmount)||0;return {from,to,out,incoming,reference:demoConvert(out,from,to),ratio:out&&incoming?incoming/out:0};}
function renderExchange(){const s=captureSession,f=s.fields,n=exchangeMath(),different=n.from!==n.to,theme=themeName();const pair=theme==='magazine'?`<div class="fx-pair editorial-fx-pair"><div><span>01 / ${t('实际转出','実際の出金')}</span><b>${n.from}</b></div><i>→</i><div><span>02 / ${t('实际到账','実際の入金')}</span><b>${n.to}</b></div></div>`:theme==='journal'?`<div class="fx-pair notebook-fx-pair"><span>${n.from}<small>${t('这边转出','こちらから出金')}</small></span><i>↝</i><span>${n.to}<small>${t('那边收到','あちらへ入金')}</small></span><b>${t('实际金额都可以改','どちらの実額も編集可')}</b></div>`:`<div class="fx-pair objects-fx-pair"><span class="fx-envelope">${n.from}<small>${t('转出的钱袋','出金のお財布')}</small></span><i>⇄</i><span class="fx-envelope">${n.to}<small>${t('到账的钱袋','入金のお財布')}</small></span></div>`;
 openSheet(different?t('换汇与转账','両替と振替'):t('账户转账','口座振替'),`${pair}<form id="entry-form" data-flow="exchange"><div class="fx-account-pair">${selectField('account',t('转出账户','出金口座'),accountOptions(a=>!isDebt(a)),f.account)}${selectField('to',t('转入账户','入金口座'),accountOptions(a=>!isDebt(a)),f.to)}</div><div class="fx-amount-pair">${field('amount',`${t('实际扣款总额','実際の出金総額')} · ${n.from}`,'number',f.amount,`min="${n.from==='JPY'?1:.01}" step="${n.from==='JPY'?1:.01}" required inputmode="decimal"`)}${field('inAmount',`${t('实际到账净额','実際の入金純額')} · ${n.to}`,'number',f.inAmount??f.amount,`min="${n.to==='JPY'?1:.01}" step="${n.to==='JPY'?1:.01}" required inputmode="decimal"`)}</div>${different?`<div class="exchange-rate-note" id="exchange-rate-note">${exchangeRateNote()}</div>${act('exchange-estimate',t('按参考汇率重新预填','参考レートで再入力'),'type="button"','fx-estimate-button')}`:`<p class="muted">${t('同币种转账，不进行汇率换算。','同じ通貨の振替。レート換算は行いません。')}</p>`}<details class="entry-details" open><summary>${t('手续费 · 避免重复扣款','手数料・二重控除しない')}</summary><div class="field-grid">${field('fee',t('明确收取的手续费 / 可留空','確定手数料・空欄可'),'number',f.fee??'','min="0" step="any"')}${selectField('feeCurrency',t('费用币种','手数料通貨'),currencyOptions(),f.feeCurrency)}</div>${selectField('feePosition',t('手续费如何扣收','手数料の扱い'),[['from-included',t('已包含在转出总额','出金総額に含む')],['to-included',t('已从到账金额扣除','入金額から控除済')],['extra',t('另行扣收','別途引落')]],f.feePosition)}${f.feePosition==='extra'?selectField('feeAccount',t('另扣手续费的账户','別途手数料の口座'),accountOptions(a=>!isDebt(a)),f.feeAccount||f.account):''}<p class="fx-fee-caption">${t('实扣与实收金额优先。已包含的费用计入支出，但不再次扣余额；不从汇差猜手续费。','実出金・実入金が基準。含まれる費用は支出へ、残高から再控除しません。差額から手数料を推定しません。')}</p></details>${selectField('transferState',t('资金状态','資金の状態'),[['confirmed',t('已转出，已到账','出金・入金済')],['inTransit',t('已转出，尚在途中','出金済・送金中')],['planned',t('只是计划，未转出','予定のみ・未出金')]],f.transferState)}<div class="field-grid">${field('date',t('转出日期','出金日'),'date',f.date,'required')}${field('arrivalDate',f.transferState==='confirmed'?t('实际到账日期','実際の入金日'):t('预计到账日期','入金予定日'),'date',f.arrivalDate,'required')}</div>${field('merchant',t('名称 / 说明','名称 / 内容'),'text',f.merchant,'required')}${field('note',t('备注','メモ'),'text',f.note)}<div class="fx-state-note">${f.transferState==='planned'?t('只是计划，不修改实际余额。','予定のみ。実残高は変更しません。'):f.transferState==='inTransit'?t('仅转出账户扣款，收款账户等待确认到账。','出金口座のみ控除。入金口座は入金確認待ち。'):t('两端按各自实扣实收记账，转账本金不计消费。','両側を実額で記録。振替元金は支出に含めません。')}</div><section class="capture-material-section"><div class="capture-material-title">${paperclip}<h3>${t('换汇凭据与附件','両替の資料と添付')}</h3></div><div id="capture-materials">${materialEditor()}</div></section><button type="submit" class="full-button">${s.context.edit?t('保存转账修改','振替の変更を保存'):t('保存这笔转账','この振替を保存')}</button><p class="exp-demo-note">${t('参考汇率为固定示例；此处只记账，不实际换汇或转账。','参考レートは固定デモ。記録のみ、実際の両替・送金は行いません。')}</p></form>`);
}
function exchangeRateNote(){const n=exchangeMath();return `<div><span>${t('参考汇率 · 示例','参考レート・デモ')}</span><b>1 ${n.from} = ${(exampleRates[n.from]/exampleRates[n.to]).toFixed(4)} ${n.to}</b><small>2026.10.12 / 09:30 · ${t('未计费用参考金额','手数料前の参考額')} ${moneyIn(n.reference,n.to)}</small></div><div><span>${t('综合到账汇率','総合入金レート')}</span><b>${n.ratio?`1 ${n.from} = ${n.ratio.toFixed(4)} ${n.to}`:'—'}</b><small>${t('由两端实际金额反算，可能含费用影响。','両側の実額から算出。費用の影響を含む場合があります。')}</small></div>`;}
function activityMetrics(a){const records=book().records.filter(r=>r.type==='expense'&&r.activity===a.id),spent=sum(records,expenseNet);return {records,spent,left:a.budget-spent};}
function activityCover(a){const m=activityMetrics(a),theme=themeName(),tag=a.excludeMonthly?t('独立预算 · 不计入月预算','独立予算・月予算に含めない'):t('计入发生月预算','利用月の予算に含む');
 if(theme==='magazine')return `<header class="activity-exp-cover editorial-trip-cover"><span class="exp-edition">A LITTLE GETAWAY / ${shortDate(a.start)} — ${shortDate(a.end)}</span><div class="editorial-trip-columns"><div><h1>${esc(label(a))}</h1><p>${tag}</p><span>${t('整段活动净消费','全期間の純支出')}</span><strong>${baseMoney(m.spent)}</strong></div><div>${tripArt.magazine}<span>${t('活动预算','シーン予算')}<b>${baseMoney(a.budget)}</b></span></div></div><footer>${t('余量','残り')} ${baseMoney(m.left)} · ${m.records.length} ${t('笔消费','件の支出')}</footer></header>`;
 if(theme==='journal')return `<header class="activity-exp-cover notebook-trip-cover"><span class="exp-tape"></span><div class="trip-date-label">${shortDate(a.start)} — ${shortDate(a.end)}</div><h1>${esc(label(a))}</h1><div class="trip-sketch">${tripArt.journal}</div><div class="trip-hand-tally"><span>${t('这一趟花了','今回の支出')}</span><strong>${baseMoney(m.spent)}</strong></div><div class="trip-hand-budget">${t('预算','予算')} ${baseMoney(a.budget)} − ${t('已花','支出')} ${baseMoney(m.spent)}<b>＝ ${t('还余','残り')} ${baseMoney(m.left)}</b></div><span class="trip-budget-stamp">${tag}</span></header>`;
 return `<header class="activity-exp-cover objects-trip-cover"><span class="trip-suitcase-handle"></span><span class="trip-sticker">${a.start.slice(5,7)}<b>${a.start.slice(-2)}</b></span><h1>${esc(label(a))}</h1><div class="trip-object-art">${tripArt.objects}</div><div class="trip-receipt-label"><span>${shortDate(a.start)} — ${shortDate(a.end)}</span><strong>${baseMoney(m.spent)}</strong><small>${t('活动预算','シーン予算')} ${baseMoney(a.budget)} · ${t('剩余','残り')} ${baseMoney(m.left)}</small></div><span class="trip-budget-tag">${tag}</span></header>`;
}
function activityPair(a,friend){const rs=book().treats.filter(r=>r.activity===a.id);return {out:sum(rs.filter(r=>r.payer==='me'),r=>r.alloc[friend.id]||0),incoming:sum(rs.filter(r=>r.payer===friend.id),r=>r.alloc.me||0)};}
function activityFriends(a){return `<div class="activity-pair-list">${a.friends.map(id=>book().friends.find(f=>f.id===id)).filter(Boolean).map(f=>{const p=activityPair(a,f),diff=p.out-p.incoming,theme=themeName();const note=diff===0?t('本活动已平衡','このシーンは均衡'):diff>0?`${t('你多替对方承担','自分が多く負担')} ${baseMoney(diff)}`:`${t('对方多替你承担','相手が多く負担')} ${baseMoney(-diff)}`;let body=theme==='magazine'?`<header><span>WITH ${esc(label(f))}</span><small>${t('仅本活动','このシーンのみ')}</small></header><div class="editorial-pair"><span>${t('你替对方承担','自分から')}<b>${baseMoney(p.out)}</b></span><i>↔</i><span>${t('对方替你承担','相手から')}<b>${baseMoney(p.incoming)}</b></span></div><footer>${note} ↗</footer>`:theme==='journal'?`<span class="pair-staple"></span><h3>${t('和','と')}${esc(label(f))}${t('的请客页','のごちそうページ')}</h3><div class="pair-hand-columns"><span>${t('我替对方','自分から')}<b>${baseMoney(p.out)}</b></span><span>${t('对方替我','相手から')}<b>${baseMoney(p.incoming)}</b></span></div><footer>↗ ${note}</footer>`:`<header><span class="friend-avatar">${esc(f.name.slice(-1))}</span><strong>${esc(label(f))}</strong><small>${t('这一趟','今回の旅')}</small></header><div class="tea-for-two"><span>${cupDrawing(p.out/(p.out+p.incoming||1))}<small>${t('你替对方','自分から')}</small><b>${baseMoney(p.out)}</b></span><i>＋</i><span>${cupDrawing(p.incoming/(p.out+p.incoming||1))}<small>${t('对方替你','相手から')}</small><b>${baseMoney(p.incoming)}</b></span></div><footer>${note} ↗</footer>`;return `<button class="exp-friend-pair ${theme}-pair" data-page="friend" data-id="${a.id}:${f.id}">${body}</button>`;}).join('')||empty(t('先在活动设置中添加同行朋友','シーン設定で同行者を追加'))}</div>`;}
screens.activity=()=>{const a=book().activities.find(a=>a.id===pageId);if(!a)return empty(t('活动不存在','シーンがありません'));const m=activityMetrics(a);return `${activityCover(a)}<div class="activity-budget-controls"><div><span>${t('资金预留','資金の確保')}</span><b class="${a.holdEnabled?'':'text-status'}">${a.holdEnabled?baseMoney(a.holdAmount):t('未开启','オフ')}</b><small>${a.holdEnabled?t('仅作资金安排，不视为已花。','資金の予定。支出済みではありません。'):t('由你主动开启，不自动预留活动预算。','自分でオンに。予算から自動確保しません。')}</small></div>${act('activity-settings',t('预算与活动设置','予算・シーン設定'),`data-id="${a.id}"`,'inline-button')}</div><div class="activity-mode-actions">${act('entry',t('记活动内一笔','シーンの一筆を記録'),`data-activity="${a.id}" data-date="${a.end<TODAY?a.end:TODAY}"`,'full-button')}${act('activity-mode',book().activeActivity===a.id?t('退出活动记账模式','シーン記録を終了'):t('持续记录这个活动','このシーンを続けて記録'),`data-id="${a.id}"`,'outline-button')}</div>${section(t('活动里的分类预算','シーン内のカテゴリ予算'),'WITHIN THIS SCENE')}<div class="activity-category-budgets">${Object.entries(a.categoryBudgets).map(([id,limit])=>{const used=sum(m.records.filter(r=>categoryContains(id,r.category)),expenseNet);return `<div><span>${catLabel(id)}</span><b>${baseMoney(used)} <small>/ ${baseMoney(limit)}</small></b>${budgetTrack(used,limit,12)}</div>`;}).join('')||`<p class="muted">${t('还没有分项预算，可在活动设置中添加。','カテゴリ予算は未設定。シーン設定から追加できます。')}</p>`}</div>${section(t('只在这一趟，轮流请客。','この旅の、ごちそうバランス。'),'GIVE & TAKE')}<p class="activity-treat-context">${t('按实际替对方承担的金额比较；自用份额不计贡献，差额不带到其他活动。','相手の分を負担した額で比較。自分の分は除外、他のシーンへ繰越しません。')}</p>${activityFriends(a)}${act('treat-other',t('记录活动内别人请我','シーンでごちそうになった記録'),`data-activity="${a.id}"`,'outline-button')}${section(t('活动里的每一笔','シーンの記録'),'DAILY NOTES')}<div class="transaction-list">${m.records.slice().sort((x,y)=>y.date.localeCompare(x.date)).map(transaction).join('')||empty(t('从活动内记账开始','シーン内の記録から始めよう'),'entry',t('记一笔','記録'))}</div>`;};
let activityDraft=null;
function editActivity(id=''){const a=book().activities.find(a=>a.id===id);activityDraft={id,values:{...(a||{}),name:a?.name||'',start:a?.start||TODAY,end:a?.end||TODAY,budget:a?.budget??'',friends:a?.friends||[],categoryBudgets:{...(a?.categoryBudgets||{})}}};renderActivityEditor();}
function stashActivity(){const form=document.getElementById('experience-activity-form');if(!form)return;const fd=new FormData(form),v=activityDraft.values;Object.assign(v,Object.fromEntries(fd),{friends:fd.getAll('friends'),excludeMonthly:fd.has('excludeMonthly'),holdEnabled:fd.has('holdEnabled')});book().categories.forEach(c=>{const n=fd.get(`activity-budget-${c.id}`);if(n!==null&&n!=='')v.categoryBudgets[c.id]=Number(n);else if(n==='')delete v.categoryBudgets[c.id];});}
function renderActivityEditor(){const v=activityDraft.values;openSheet(t('活动预算与资金安排','シーン予算と資金予定'),`<form id="experience-activity-form"><div class="activity-settings-caption">${t('三个独立设置，不混为同一个金额。','三つの設定を、同じ金額にしない。')}</div>${field('name',t('活动名称','シーン名'),'text',v.name,'required')}<div class="field-grid">${field('start',t('开始日期','開始日'),'date',v.start,'required')}${field('end',t('结束日期','終了日'),'date',v.end,'required')}</div><section class="activity-setting-section"><span class="setting-step">01</span><h3>${t('活动自己的预算','シーン自身の予算')}</h3>${field('budget',`${t('整段活动总预算','全期間の予算')} · ${bookCurrency()}`,'number',v.budget,'min="0" step="any" required')}<details class="entry-details" open><summary>${t('活动内分类预算','シーン内カテゴリ予算')}</summary>${orderedCategories().map(c=>field(`activity-budget-${c.id}`,categoryPath(c.id),'number',v.categoryBudgets[c.id]??'','min="0" step="any"')).join('')||`<p class="muted">${t('分类由你创建，创建后可添加活动内预算。','カテゴリ作成後にシーン内予算を設定できます。')}</p>`}</details></section><section class="activity-setting-section"><span class="setting-step">02</span><h3>${t('与月预算的关系','月予算との関係')}</h3>${expToggle('excludeMonthly',t('不计入月预算','月予算に含めない'),t('不占用发生月的总/分类预算；实际消费、余额和还款仍包含。','利用月の全体・カテゴリ予算から除外。実支出・残高・返済は含む。'),v.excludeMonthly)}<div class="activity-setting-example">${v.excludeMonthly?t('已开启：本活动全部关联消费只占活动预算，月预算页单列独立活动支出。','オン：シーン予算のみ使用。月予算では独立支出として別表示。'):t('未开启：活动消费同时计入实际发生月份的预算，只记录一次消费。','オフ：利用月の予算にも計上。支出は一回のみ。')}</div></section><section class="activity-setting-section"><span class="setting-step">03</span><h3>${t('先留好资金 / 可选','資金を確保・任意')}</h3>${expToggle('holdEnabled',t('为活动预留资金','シーンの資金を確保'),t('默认关闭，金额不必等于预算。只是安排，不是支出。','初期はオフ。予算と同額でなくても可。予定であって支出ではない。'),v.holdEnabled)}${v.holdEnabled?field('holdAmount',`${t('计划预留金额','確保予定額')} · ${bookCurrency()}`,'number',v.holdAmount||'','min="0" step="any"'):''}<p class="muted">${t('独立活动与未来月份活动的资金预留，不扣当前月预算余额。','独立シーンや翌月以降の資金確保は今月の予算残額から引きません。')}</p></section><section class="activity-setting-section"><h3>${t('同行朋友','同行者')}</h3><div class="friend-checkboxes">${book().friends.map(f=>`<label><input name="friends" type="checkbox" value="${f.id}" ${v.friends.includes(f.id)?'checked':''}><span>${esc(label(f))}</span></label>`).join('')}</div>${act('activity-add-friend',`＋ ${t('添加同行朋友','同行者を追加')}`,'type="button"','text-link')}</section><div class="setup-note">${t('修改预算归属会更新本活动已有记录的预算口径，不改变原记录的金额和日期。','予算区分の変更は既存記録にも適用。元の金額・日付は変更しません。')}</div><button class="full-button" type="submit">${t('保存活动设置','シーン設定を保存')}</button></form>`);}
friendCards=()=>`<div class="friend-directory-intro">${experienceArt[themeName()]}<h2>${t('一起出游的人。','一緒に出かける人。')}</h2><p>${t('朋友资料可以复用；请客差额只在各自活动里查看，不做长期累计。','友人情報は再利用。ごちそう差額は各シーン内で、長期合算しません。')}</p></div><div class="friend-directory">${book().friends.map(f=>{const activities=book().activities.filter(a=>a.friends.includes(f.id));return `<button data-page="friend" data-id="${f.id}"><span class="friend-avatar">${esc(f.name.slice(-1))}</span><strong>${esc(label(f))}</strong><small>${activities.length} ${t('个活动','件のシーン')}</small><span>↗</span></button>`;}).join('')}</div>${act('new-friend',`＋ ${t('添加朋友资料','友人情報を追加')}`,'','outline-button')}`;
screens.friend=()=>{const [aId,fId]=pageId.includes(':')?pageId.split(':'):['',pageId],f=book().friends.find(f=>f.id===fId);if(!f)return empty('—');const a=book().activities.find(a=>a.id===aId);if(!a)return `${experienceLead('friend-directory',esc(label(f)),t('每个活动单独查看，差额不跨活动累计。','シーンごとに確認。差額は合算しません。'),'SHARED MOMENTS')}<div class="friend-activity-links">${book().activities.filter(a=>a.friends.includes(f.id)).map(a=>pageButton('friend',`${esc(label(a))} · ${shortDate(a.start)} — ${shortDate(a.end)}`,`${a.id}:${f.id}`,'list-button')).join('')||empty(t('还没有一起参加的活动','一緒のシーンはまだありません'))}</div>`;const p=activityPair(a,f),diff=p.out-p.incoming;return `${experienceLead('friend',`${t('我和','自分と')}${esc(label(f))}`,`${esc(label(a))} · ${a.start} — ${a.end}`,'WITHIN THIS SCENE',baseMoney(Math.abs(diff)),diff>=0?t('你多替对方承担','自分が多く負担'):t('对方多替你承担','相手が多く負担'))}<div class="pair-detail-totals">${rows([[t('你替对方承担','自分が相手の分を負担'),baseMoney(p.out)],[t('对方替你承担','相手が自分の分を負担'),baseMoney(p.incoming)]])}</div><div class="dual-actions">${act('treat-me',t('我请客','ごちそうした'),`data-activity="${a.id}" data-friend="${f.id}"`,'full-button')}${act('treat-other',t('别人请我','ごちそうになった'),`data-activity="${a.id}" data-friend="${f.id}"`,'outline-button')}</div>${section(t('本活动往来明细','このシーンのごちそう'),'ACTUAL CONTRIBUTIONS')}<div class="pair-history">${book().treats.filter(r=>r.activity===a.id&&(r.payer==='me'&&r.alloc[f.id]||r.payer===f.id&&r.alloc.me)).map(r=>`<article><span>${shortDate(r.date)}</span><div><strong>${esc(r.merchant)}</strong><small>${r.payer==='me'?t('你付款','自分が支払'):t('对方付款','相手が支払')} · ${t('整单','総額')} ${baseMoney(r.amount)}</small><p>${r.payer==='me'?t('其中替对方承担','うち相手の分'):t('其中替你承担','うち自分の分')} <b>${baseMoney(r.payer==='me'?r.alloc[f.id]:r.alloc.me)}</b></p></div></article>`).join('')||empty(t('本活动还没有往来记录','このシーンの記録はありません'))}</div>${pageButton('activity',t('回到活动','シーンへ戻る'),a.id)}`;};
let otherTreatContext=null;
treatOther=(friend,activityId)=>{const a=book().activities.find(a=>a.id===activityId);if(!a)return;otherTreatContext={activity:a.id};const participants=a.friends.map(id=>book().friends.find(f=>f.id===id)).filter(Boolean);if(!participants.length){editActivity(a.id);return;}openSheet(t('活动内 · 别人请我','シーン内・ごちそうになった'),`<form id="treat-form"><div class="treat-activity-caption">${esc(label(a))} · ${a.start} — ${a.end}</div><input type="hidden" name="activity" value="${a.id}">${selectField('payer',t('实际付款朋友','支払った友人'),participants.map(f=>[f.id,label(f)]),friend||participants[0].id)}${field('amount',`${t('整单金额','支払総額')} · ${bookCurrency()}`,'number','','min="1" required')}${field('merchant',t('商户 / 说明','お店 / 内容'),'text','','required')}${field('date',t('活动内发生日期','シーン内の利用日'),'date',a.end<TODAY?a.end:a.start>TODAY?a.start:TODAY,'required')}<p class="muted">${t('付款人和你默认均分；可加入其他共同消费的人。只记录对方替你承担的份额，不记录朋友彼此往来。','支払者と自分で均等配分。他の参加者も追加可。相手が自分の分を負担した額のみ集計。')}</p><div class="friend-checkboxes">${participants.map(f=>`<label><input name="friends" type="checkbox" value="${f.id}" data-friend-check><span>${esc(label(f))}</span></label>`).join('')}</div><div id="allocations"></div><div class="setup-note">${t('不会扣你的账户，也不计入你的实际消费。','自分の残高・実支出に計上しません。')}</div><button type="submit" class="full-button">${t('保存本活动往来','このシーンの記録を保存')}</button></form>`);refreshAllocations();};
const analysisModules={categories:{name:['分类消费','カテゴリ支出'],note:['钱花在什么用途','お金の使い道'],icon:'bag'},merchants:{name:['商户消费','お店の支出'],note:['常去哪里，花了多少','よく行くお店と金額'],icon:'coffee'},trend:{name:['消费趋势','支出の推移'],note:['每天的节奏与同期变化','日々のペースと前月比較'],icon:'chart'},activities:{name:['活动消费','シーン支出'],note:['每段出游单独看清','旅ごとの支出を見る'],icon:'life'}};
function analysisModule(id,d,first=false){const theme=themeName(),meta=analysisModules[id];let content='';if(id==='categories'){
 if(theme==='magazine')content=`<div class="custom-editorial-categories">${d.categories.map((c,i)=>`<button data-action="category-detail" data-id="${c.id}"><span>${String(i+1).padStart(2,'0')}</span><div><strong>${t(...c.name)}</strong><small>${c.count} ${t('笔','件')} · ${Math.round(c.amount/(d.total||1)*100)}%</small></div><b>${baseMoney(c.amount)}</b></button>`).join('')}</div>`;
 if(theme==='journal')content=`<div class="custom-notebook-categories"><div>${t('用途','使い道')}<span>${t('金额','金額')}</span></div>${d.categories.map(c=>`<button data-action="category-detail" data-id="${c.id}"><span>□ ${t(...c.name)}</span><b>${baseMoney(c.amount)}</b><small>${c.count} ${t('笔小花费','件の支出')}</small></button>`).join('')}</div>`;
 if(theme==='objects')content=`<div class="custom-category-pockets">${d.categories.map((c,i)=>`<button class="custom-category-pocket color-${i%3}" data-action="category-detail" data-id="${c.id}">${icon(c.icon)}<strong>${t(...c.name)}</strong><b>${baseMoney(c.amount)}</b><small>${Math.round(c.amount/(d.total||1)*100)}% · ${c.count} ${t('笔','件')}</small></button>`).join('')}</div>`;
 }else if(id==='merchants'){
 if(theme==='magazine')content=`<div class="custom-editorial-shops">${d.merchants.map(([name,amount],i)=>`<button data-action="merchant-detail" data-name="${esc(name)}"><span>SHOP / ${String(i+1).padStart(2,'0')}</span><strong>${esc(name)}</strong><b>${baseMoney(amount)}</b><small>${d.rs.filter(r=>r.merchant===name).length} ${t('次消费','回の支出')}</small></button>`).join('')}</div>`;
 if(theme==='journal')content=`<div class="custom-notebook-shops">${d.merchants.map(([name,amount],i)=>`<button data-action="merchant-detail" data-name="${esc(name)}"><span>${String(i+1).padStart(2,'0')}</span><strong>${esc(name)}</strong><b>${baseMoney(amount)}</b></button>`).join('')}</div>`;
 if(theme==='objects')content=`<div class="custom-shop-slip"><header>MY LITTLE SHOPS ${icon('coffee')}</header>${d.merchants.map(([name,amount])=>`<button data-action="merchant-detail" data-name="${esc(name)}"><strong>${esc(name)}</strong><b>${baseMoney(amount)}</b></button>`).join('')}<footer>${t('合计','合計')} <b>${baseMoney(d.total)}</b></footer></div>`;
 }else if(id==='trend')content=themedTrend(d).replace(/^<div class="section-head[^>]*>.*?<\/div>/s,'');else content=activityCards();
 if(!d.rs.length&&id!=='activities')content=empty(t('这个区间还没有消费记录','この期間の支出はありません'));
 return `<section class="custom-analysis-module module-${id} ${first?'focus-module':''}"><div class="custom-module-heading"><span>${first?t('重点关注','注目'):t('我的分析','マイ分析')}</span><h2>${t(...meta.name)}</h2><small>${t(...meta.note)}</small></div>${content}</section>`;
}
screens.analysis=()=>{const prefs=book().analysisPrefs?.order||(analysisPreview?['categories','merchants','trend']:null),d=categoryData();let body='';if(analysisTab==='spend')body=prefs?.length?`${experienceLead('analysis',t('从你的重点，看日常。','自分の視点で、日々を見る。'),`${analysisMonth} · ${d.rs.length} ${t('笔记录','件の記録')} · ${t('含独立活动实际消费','独立シーンの実支出を含む')}`,'MONEY IN CONTEXT',baseMoney(d.total),analysisPreview&&!book().analysisPrefs?t('示例布局 · 未保存','サンプル配置・未保存'):d.rs.some(r=>r.settlementState==='pending')?t('净消费含预计换算','純支出に仮換算を含む'):t('本位币净消费','基準通貨の純支出'))}<div class="analysis-own-controls">${pageButton('analysis-custom',t('自定义显示与顺序','表示と順序を設定'))}${analysisPreview&&!book().analysisPrefs?act('analysis-clear-preview',t('退出示例','サンプル終了')):''}</div>${prefs.map((id,i)=>analysisModule(id,d,i===0)).join('')}`:`${experienceLead('analysis-empty',t('你想先看清什么？','まず、何を見たい？'),t('分类、商户、趋势和活动，选择你关心的内容与顺序。','カテゴリ・お店・推移・シーン。気になる内容と順序を選んで。'),'YOUR OWN PERSPECTIVE')}<div class="analysis-empty-choices">${Object.entries(analysisModules).map(([id,m],i)=>`<button data-action="analysis-add-focus" data-id="${id}"><span>${String(i+1).padStart(2,'0')}</span>${icon(m.icon)}<strong>${t(...m.name)}</strong><small>${t(...m.note)}</small></button>`).join('')}</div>${pageButton('analysis-custom',t('选择模块与排序','モジュールと順序を選択'),'','full-button')}${act('analysis-preview',t('先看看示例排版','サンプル配置を見てみる'),'','text-link')}<p class="exp-demo-note">${t('未选择时不替你预设重点，偏好按账本保存。','未選択の視点は自動設定しません。帳簿ごとに保存。')}</p>`;else body=analysisTab==='budget'?budgetView():forecastView();return `${tabs([['spend',t('消费','支出')],['budget',t('预算','予算')],['future',t('未来','未来')]],analysisTab,'data-analysis')}${analysisFilters()}${body}`;};
screens['analysis-custom']=()=>{const order=[...analysisDraft,...Object.keys(analysisModules).filter(id=>!analysisDraft.includes(id))];return `${experienceLead('customize',t('把重点，摆在前面。','見たいものを、先頭へ。'),t('勾选想看的模块，调整顺序。第一个模块作为重点。','見たい内容を選択し、順序を変更。先頭が注目モジュール。'),'MY ANALYSIS / EDIT')}<div class="analysis-custom-caption"><span>${t('已选','選択')} ${analysisDraft.length}</span><span>${t('当前账本','現在の帳簿')} · ${esc(label(book()))}</span></div><div class="analysis-custom-list">${order.map((id,i)=>{const m=analysisModules[id],chosen=analysisDraft.includes(id),index=analysisDraft.indexOf(id);return `<article class="analysis-custom-item ${chosen?'selected':''}"><label><input type="checkbox" data-analysis-module="${id}" ${chosen?'checked':''}><span class="module-rank">${chosen?String(index+1).padStart(2,'0'):'—'}</span><span class="module-choice-icon">${icon(m.icon)}</span><div><strong>${t(...m.name)}</strong><small>${t(...m.note)}</small></div></label>${chosen?`<div class="module-order-controls">${act('analysis-move','↑',`data-id="${id}" data-direction="-1" ${index===0?'disabled':''} aria-label="${t('上移','上へ')} ${t(...m.name)}"`,'order-button')}${act('analysis-move','↓',`data-id="${id}" data-direction="1" ${index===analysisDraft.length-1?'disabled':''} aria-label="${t('下移','下へ')} ${t(...m.name)}"`,'order-button')}</div>`:''}${chosen&&index===0?`<span class="focus-tag">${t('重点','注目')}</span>`:''}</article>`;}).join('')}</div><div class="analysis-layout-summary"><span>${t('预览阅读顺序','表示順のプレビュー')}</span><div>${analysisDraft.map(id=>`<span>${t(...analysisModules[id].name)}</span>`).join('<i>→</i>')||t('尚未选择模块','モジュール未選択')}</div></div>${act('analysis-apply',t('应用到我的分析页','マイ分析に適用'),'','full-button')}${act('analysis-use-example',t('填入一组示例选项','サンプル選択を入れる'),'','text-link')}<p class="exp-demo-note">${t('只改变显示与顺序，不改变账目、预算口径或分析数据。','表示と順序のみ変更。記録・予算基準・分析データは変更しません。')}</p>`;};
function financialTotals(){const as=book().accounts;return {funds:sum(as.filter(a=>!isDebt(a)),a=>demoConvert(a.balance,a.currency,bookCurrency())),debt:sum(as.filter(isDebt),a=>demoConvert(a.balance,a.currency,bookCurrency()))};}
function multiAccountCard(a){const theme=themeName(),route=a.type==='loan'?'loan':isDebt(a)?'credit':'bank';if(theme==='magazine')return `<button class="exp-account editorial-account" data-page="${route}" data-id="${a.id}"><span>${a.currency}</span><div><strong>${esc(label(a))}</strong><small>${isDebt(a)?`${t('下次','次回')} ${shortDate(a.date)} · ${accountMoney(a,a.next)}`:t('保留原币余额','元通貨の残高を保持')}</small></div><b>${accountMoney(a,a.balance)}</b><i>↗</i></button>`;if(theme==='journal')return `<button class="exp-account notebook-account" data-page="${route}" data-id="${a.id}"><span class="account-ink-mark">${a.currency}</span><strong>${esc(label(a))}</strong><b>${accountMoney(a,a.balance)}</b><small>${isDebt(a)?`${shortDate(a.date)} · ${t('应还','支払')} ${accountMoney(a,a.next)}`:t('余额记在这一页','残高をこのページに')}</small></button>`;return `<button class="exp-account objects-account ${isDebt(a)?'debt-object-account':''}" data-page="${route}" data-id="${a.id}"><span class="account-object-tab">${a.currency}</span><strong>${esc(label(a))}</strong><b>${accountMoney(a,a.balance)}</b><small>${isDebt(a)?`${t('下次应还','次回支払')} ${accountMoney(a,a.next)}`:t('可用余额','利用可能残高')}</small><i>↗</i></button>`;}
screens.accounts=()=>{const n=financialTotals(),as=book().accounts;return `${experienceLead('accounts',t('钱与欠款，都有位置。','お金も借入も、それぞれに。'),t('账户保留原币；汇总只做本位币参考估值。','口座は元通貨。集計は基準通貨の参考評価。'),'A PLACE FOR EVERY CURRENCY',baseMoney(n.funds),t('资金参考合计','資金の参考合計'))}<div class="accounts-reference-note"><span>${t('未偿还本金参考合计','未返済元金の参考合計')} <b>${baseMoney(n.debt)}</b></span><small>${t('汇率为设计示例，信用额度不计入资金。','レートはデモ。利用枠は資金に含めません。')}</small></div><div class="exp-account-shortcuts">${act('exchange-open',`${t('转账 / 换汇','振替・両替')}${icon('transfer')}`,'','shortcut')}${pageButton('calendar',t('还款日历','支払日'),'','shortcut')}${pageButton('reconcile',t('账单核对','明細照合'),'','shortcut')}</div>${section(t('持有的资金','持っている資金'),'AVAILABLE FUNDS')}<div class="exp-account-list">${as.filter(a=>!isDebt(a)).map(multiAccountCard).join('')||empty(t('添加第一个账户','最初の口座を追加'),'new-account',t('添加账户','口座を追加'))}</div>${section(t('信用卡与借款','カードと借入'),'TO REPAY')}<div class="exp-account-list">${as.filter(isDebt).map(multiAccountCard).join('')}</div>${act('new-account',`＋ ${t('添加账户','口座を追加')}`,'','full-button')}`;};
screens.bank=()=>{const a=account(pageId);if(!a)return empty('—');return `${experienceLead('bank',esc(label(a)),`${a.currency} · ${t('账户原币余额','口座の元通貨残高')}`,'AVAILABLE BALANCE',accountMoney(a,a.balance),`${t('本位币参考','基準通貨参考')} ${baseMoney(demoConvert(a.balance,a.currency,bookCurrency()))}`)}<div class="dual-actions">${act('exchange-open',t('从这个账户转账 / 换汇','この口座から振替・両替'),`data-from="${a.id}"`,'full-button')}${act('edit-account',t('编辑账户','口座を編集'),`data-id="${a.id}"`,'outline-button')}</div>${pageButton('reconcile',t('核对账户流水','口座明細を照合'))}${section(t('账户流水','口座の記録'),'RECENT')}<div class="transaction-list">${book().records.filter(r=>r.account===a.id||r.to===a.id).slice().reverse().map(transaction).join('')||empty(t('还没有流水，余额来自期初状态。','記録はまだありません。残高は期首情報から。'))}</div>`;};
screens.loan=()=>{const a=account(pageId);if(!a)return empty('—');const revolving=a.loanMode==='revolving'||a.id==='loan',plan=a.manualPlan||[];return `${experienceLead('loan',esc(label(a)),`${a.currency} · ${revolving?t('循环额度借款','利用枠内の借入'):t('固定计划借款','固定計画の借入')}`,'MY BORROWING',accountMoney(a,a.balance),t('剩余未还本金','未返済元金'))}${revolving?`<div class="loan-available-limit"><span>${t('参考利用可能额 / 不属于资金','参考利用可能額・資金には含めません')}</span><strong class="${a.limit?'':'text-status'}">${a.limit?accountMoney(a,Math.max(0,a.limit-a.balance)):t('尚未填写额度','利用枠は未入力')}</strong><small>${t('恢复时点等待用户规则确认','枠の回復時点は手動条件の確認待ち')}</small></div>`:''}<div class="loan-next-payment"><span>${shortDate(a.date)}</span><div><strong>${t('下次已确认应还','次回確定支払額')}</strong><small>${esc(label(account(a.bank)))} · ${accountCurrency(a.bank)}</small></div><b>${accountMoney(a,a.next)}</b></div>${account(a.bank)&&demoConvert(account(a.bank).balance,accountCurrency(a.bank),a.currency)<a.next?`<div class="exp-risk-card"><div><strong>${t('扣款账户尚未备足','引落口座が不足')}</strong><p>${t('请先兑换并确认到账，再记录实际还款。','先に両替・入金を確認し、実際の返済を記録。')}</p></div>${act('exchange-open',t('准备换汇','両替を準備'),`data-from="bank-s" data-to="${a.bank}"`,'inline-button')}</div>`:''}<div class="dual-actions">${act('entry',t('记录实际还款','実際の返済を記録'),`data-type="repayment" data-account="${a.bank}" data-to="${a.id}"`,'full-button')}${act('edit-account',t('编辑期初与计划','期首・計画を編集'),`data-id="${a.id}"`,'outline-button')}</div>${section(t('未来逐月安排','月別の予定'),'KNOWN SCHEDULE')}<div class="loan-plan-table"><div class="loan-plan-head"><span>${t('月份','月')}</span><span>${t('本金','元金')}</span><span>${t('费用','費用')}</span><span>${t('剩余','残額')}</span></div>${plan.map(row=>`<div class="loan-plan-row"><span>${row.month}</span><b>${(row.principal==null?t('未补齐','未補足'):accountMoney(a,row.principal))}</b><span>${(row.fee==null?t('未补齐','未補足'):accountMoney(a,row.fee))}</span><span>${(row.left==null?t('未补齐','未補足'):accountMoney(a,row.left))}</span><small>${t('应还总额','支払総額')} ${accountMoney(a,row.pay)} · ${t('手动已知计划','手動の既知計画')}</small></div>`).join('')||empty(t('尚未填写完整规则或逐月计划','計算条件・月別計画は未設定'))}</div><div class="loan-rule-state"><h3>${a.loanRules?t('规则资料已保存，继续核实细节','条件情報は保存済・詳細を確認'):t('规则尚未完整配置','計算条件は未設定')}</h3><p>${t('已知应还可用于提醒。完整利息、提前还款、再次借入与额度恢复，在补齐规则后才能准确预测。','既知の支払額は通知に使用。利息・繰上返済・再借入・枠回復は条件補足後に予測。')}</p>${act('loan-rules',t('填写此账户的规则','この口座の条件を設定'),`data-id="${a.id}"`,'outline-button')}</div>`;};
function loanRuleEditor(id){const a=account(id);openSheet(t('借款规则 · 手动填写','借入条件・手入力'),`<form id="loan-rule-form" data-id="${id}"><div class="setup-note">${t('日本与中国平台共用结构化表单，不按国家或名称预设规则。','日本・中国とも構造化入力。国や名称で条件を推定しません。')}</div>${selectField('method',t('还款计算方式','返済計算方式'),[['manual',t('先填平台已知计划','既知の返済計画から')],['equal-principal',t('等额本金','元金均等')],['equal-payment',t('等额本息','元利均等')],['interest-first',t('按期付息，到期还本','利息払い・満期元金返済')],['revolving',t('循环借入与还款规则','反復借入・返済条件')]],a.loanRules?.method||'manual')}${field('apr',t('年利率 / 若适用（%）','年利率・適用時（%）'),'number',a.loanRules?.apr||'','min="0" step="any"')}${selectField('interest',t('计息方式','利息計算'),[['daily',t('按日计息','日単位')],['monthly',t('按月计息','月単位')]],a.loanRules?.interest||'daily')}${field('serviceFee',t('另收服务费 / 若适用','別途サービス料・適用時'),'number','','min="0" step="any"')}${field('restore',t('额度恢复时点 / 手动说明','枠回復時点・手動メモ'),'text',a.loanRules?.restore||'')}<p class="muted">${t('尚未确定的信息可稍后补齐，已知还款计划与预测分开展示。','未確定の情報は後から補足。既知の計画と予測は区別します。')}</p><button type="submit" class="full-button">${t('保存规则信息','条件情報を保存')}</button></form>`);}
screens['fx-check']=()=>{const r=book().records.find(r=>r.id==='fx1');if(!r)return `${experienceLead('fx-empty',t('换算差异，逐笔确认。','換算の差は、一件ずつ。'),t('有外币消费时，在这里比较预计与实际入账。','外貨利用の見込みと実計上額を比較します。'),'CURRENCY RECONCILIATION')}${empty(t('本账本暂无外币核对示例','この帳簿に外貨照合サンプルはありません'))}`;const confirmed=r.settlementState==='confirmed',difference=15230-(r.accountAmount??r.amount);return `${experienceLead('fx-check',t('同一笔消费，两种金额。','同じ一件、二つの金額。'),t('原币帮助定位，最终以账户币种的实际入账核对。','原通貨は候補の手がかり。口座通貨の実計上額で照合。'),'CHECK THE CONVERSION')}<div class="fx-check-source"><span>${esc(label(account(r.account)))} · JPY</span><b>${confirmed?t('入账已确认','計上確認済'):r.differenceConfirmed?t('已确认差异 · 金额仍预计','差額確認済・金額は見込み'):t('换算待确认','換算未確定')}</b></div><div class="fx-check-original"><span>${t('原币消费一致','原通貨の利用額が一致')}</span><strong>US$100.00</strong><small>BOOKS & COFFEE ONLINE · 2026.10.08</small></div><div class="fx-check-amounts"><div><span>${t('手动记账','手動記録')}</span><b>${moneyIn(r.accountAmount||r.amount,'JPY')}</b><small>${confirmed?t('实际入账','実計上'):t('预计换算','換算見込み')}</small></div><i>↔</i><div><span>${t('导入账单','取込明細')}</span><b>¥15,230</b><small>${t('JPY 实际入账','JPY 実計上額')}</small></div></div><div class="fx-difference-note"><span>${confirmed?t('已确认同一笔，金额一致','同一取引・金額一致を確認'):t('差额','差額')}</span><strong>${confirmed?'¥0':`${difference>=0?'+':''}${moneyIn(difference,'JPY')}`}</strong><p>${t('原币金额与购买日期一致。差额可能来自换算；不自动称为手续费，也不直接标记为完全匹配。','原通貨額と購入日が一致。換算差の可能性。手数料と断定せず、完全一致として自動処理しません。')}</p></div>${!confirmed?act('fx-confirm-preview',t('确认实际入账金额','実計上額を確認'),'data-id="fx1"','full-button'):act('transaction',t('查看确认后的原记录','確認済みの元記録を見る'),'data-id="fx1"','full-button')}${pageButton('reconcile',t('回到账单核对','明細照合へ戻る'))}<div class="fx-reconciliation-boundary">${t('导入资料不改账。只有进入金额确认并保存，才更新原条目；原币与原预计值保留。','取込資料は記録を変更しません。実額を確認・保存して元記録を更新。原通貨と旧見込みを保持。')}</div>`;};
function fxConfirmPreview(id){const r=book().records.find(r=>r.id===id);openSheet(t('保存实际入账前，再看一次。','実計上額を保存する前に。'),`<div class="fx-confirm-header"><span>REVIEW / NOT AN AUTOMATIC IMPORT</span><h3>${esc(r.merchant)}</h3></div>${rows([[t('原币','原通貨'),'US$100.00'],[t('原预计入账','元の計上見込み'),moneyIn(r.accountAmount??r.amount,'JPY')],[t('实际入账','実際の計上額'),'¥15,230'],[t('原消费月预算变化','購入月の予算変更'),moneyIn(15230-(r.accountAmount??r.amount),'JPY')],[t('记录 ID','記録ID'),r.id]])}<div class="setup-note">${t('更新原记账，不新增消费。若它属于独立活动，仍沿用活动的预算归属。','元の記録を更新。新規支出は作りません。独立シーンならその予算区分を維持。')}</div>${act('fx-confirm-save',t('确认并保存实际金额','実額を確認して保存'),`data-id="${id}"`,'full-button')}${act('fx-keep-difference',t('保留原记录，只确认差异','元記録を保持し差額のみ確認'),`data-id="${id}"`,'outline-button')}`);}
const reconcileBeforeExperience=screens.reconcile;screens.reconcile=()=>`${reconcileBeforeExperience()}<div class="fx-reconcile-entry"><h3>${t('外币消费与汇率差异','外貨利用と換算差')}</h3><p>${t('预计换算与实际入账分开，差额不直接当漏记或手续费。','換算見込みと実計上額を区別。差額を記録漏れ・手数料と断定しません。')}</p>${pageButton('fx-check',t('查看外币核对示例','外貨照合サンプルを見る'),'','outline-button')}</div>`;
function knownTimeline(){const actual=Object.fromEntries(book().accounts.filter(a=>!isDebt(a)).map(a=>[a.id,a.balance])),withIncome={...actual};return events().map(e=>{const a=account(e.account),currency=e.kind==='repayment'?accountCurrency(e.id):accountCurrency(e.account),amount=Math.abs(e.out),converted=demoConvert(amount,currency,a?.currency||currency);if(e.kind==='income')withIncome[e.account]=(withIncome[e.account]||0)+converted;else{actual[e.account]=(actual[e.account]||0)-converted;withIncome[e.account]=(withIncome[e.account]||0)-converted;}return {...e,currency,amount,bankCurrency:a?.currency||currency,baseline:actual[e.account]||0,including:withIncome[e.account]||0,needsExchange:currency!==a?.currency};});}
forecastView=()=>{const n=homeNumbers(),daily=sum(expenses().filter(r=>!r.activity&&r.category!=='housing'&&r.payment!=='fee'),expenseNet)/12,predicted=n.used+reserve()+daily*19;return `${experienceLead('future',t('提前一点，看见压力。','少し先の、負担を見よう。'),t('预算风险与扣款账户风险分开；预计收入不隐藏当前缺口。','予算と引落口座のリスクを区別。見込み収入で不足を隠しません。'),'A LITTLE AHEAD')}<div class="future-budget-scenario"><span>${t('消费趋势 · 示例推算','支出推移・デモ予測')}</span><strong>${predicted>book().budget?t('月底可能超预算','月末に予算超過の見込み'):t('按目前节奏仍有余量','現在のペースでは予算内')}</strong><b>${baseMoney(Math.max(0,predicted-book().budget))}</b><p>${t('示例按已记日常消费均速推算剩余 19 天，不外推活动与固定账单；固定预留另计。','記録済み日常支出の平均で残り19日を推計。シーン・固定費は外挿せず、固定費予定は別途。')}</p></div>${section(t('实际扣款账户的时间线','引落口座ごとの予定'),'ACCOUNT BY ACCOUNT')}<div class="future-account-timeline">${knownTimeline().map(e=>`<article class="future-timeline-row ${e.baseline<0&&e.kind!=='income'?'at-risk':''}"><span class="future-date">${shortDate(e.date)}</span><div><strong>${esc(label(e))}</strong><small>${esc(label(account(e.account)))} · ${e.currency}</small><p>${e.kind==='income'?t('未到账预计收入，仅进入收入情景。','未入金の見込み収入。収入シナリオのみに反映。'):`${t('不含预计收入时，付款后余额','見込み収入なしの支払後残高')} ${moneyIn(e.baseline,e.bankCurrency)}`}</p>${e.kind!=='income'?`<small>${t('含预计收入的情景','見込み収入あり')} ${moneyIn(e.including,e.bankCurrency)}</small>`:''}${e.needsExchange?`<span class="tag">${t('币种不同，需确认换汇','通貨が異なるため両替確認')}</span>`:''}</div><b>${e.kind==='income'?'+':'−'}${moneyIn(e.amount,e.currency)}</b></article>`).join('')||empty(t('先添加账户或已知付款安排','口座や既知の予定を追加してください'))}</div>${section(t('活动资金与在途转账','シーン資金と送金中'),'RESERVED / IN TRANSIT')}<div class="future-planned-funds">${book().activities.filter(a=>a.holdEnabled).map(a=>`<div><strong>${esc(label(a))}</strong><span>${baseMoney(a.holdAmount)}</span><small>${t('活动资金预留，不是已花。','シーンの資金確保。支出済みではありません。')}</small></div>`).join('')||`<p class="muted">${t('活动资金预留默认关闭，由你主动开启。','シーン資金の確保は初期オフ。自分でオンに。')}</p>`}${book().records.filter(r=>r.transferState&&r.transferState!=='confirmed').map(r=>`<div><strong>${esc(r.merchant)}</strong><span>${r.transferState==='planned'?t('计划','予定'):t('在途','送金中')}</span><small>${recordMainMoney(r)} → ${moneyIn(r.toAmount,accountCurrency(r.to))} · ${r.arrivalDate}</small></div>`).join('')}</div>${act('expected-income',t('添加手动预计收入','収入見込みを手入力'),'','outline-button')}`;};
screens.calendar=()=>`${experienceLead('calendar',t('接下来的每一天。','これからの支払日。'),t('金额保留付款币种，点开查看对应账户。','金額は支払通貨を保持。口座へ進んで確認。'),'PAYMENT CALENDAR')}<div class="exp-calendar-list">${knownTimeline().map(e=>`<button data-page="${e.kind==='repayment'?(account(e.id)?.type==='loan'?'loan':'credit'):e.kind==='bill'?'recurring':'forecast'}" data-id="${e.id}"><span>${shortDate(e.date)}</span><div><strong>${esc(label(e))}</strong><small>${esc(label(account(e.account)))} · ${e.kind==='income'?t('预计收入','収入見込み'):e.confirmed?t('已确认','確定'):t('已知 / 预计安排','既知・予定')}</small></div><b>${e.kind==='income'?'+':'−'}${moneyIn(e.amount,e.currency)}</b></button>`).join('')||empty(t('暂无安排','予定はありません'))}</div>${pageButton('forecast',t('检查未来资金缺口','将来の不足を確認'))}`;
screens.forecast=forecastView;
const settingsBeforeExperience=screens.settings;screens.settings=()=>settingsBeforeExperience()+`<div class="panel experience-settings"><h3>${t('按你的方式开始','自分のやり方で始める')}</h3>${pageButton('onboarding',t('首次设置与期初状态预览','初回設定・期首情報のプレビュー'),'','settings-row')}${pageButton('analysis-custom',t('我的分析模块与顺序','マイ分析の内容と順序'),'','settings-row')}${act('exchange-open',t('转账与换汇','振替と両替'),'','settings-row')}</div>`;
const lifeBeforeExperience=screens.life;screens.life=()=>lifeBeforeExperience().replace(t('朋友往来','ごちそう'),t('参与朋友','同行の友人'));
function experienceBeforeNavigate(name){if(name==='analysis-custom')analysisDraft=[...(book().analysisPrefs?.order||[])];}
function experienceAction(name,el){
 const id=el.dataset.id;
 if(name==='switch-book'){analysisPreview=false;setupState={step:0,name:'',base:'JPY',budget:'',date:TODAY,accounts:[]};return false;}
 if(name==='new-account'||name==='edit-account'){beginAccountEditor(id);return true;}
 if(name==='setup-start'){setupState.step=1;render();return true;}
 if(name==='setup-next'){setupState.step++;render();window.scrollTo(0,0);return true;}
 if(name==='setup-back'){setupState.step=Math.max(0,setupState.step-1);render();window.scrollTo(0,0);return true;}
 if(name==='setup-add-account'){beginAccountEditor('',true,el.dataset.debt==='true');return true;}
 if(name==='setup-edit-account'){beginAccountEditor(id,true);return true;}
 if(name==='setup-sample'){const debt=el.dataset.debt==='true',existing=setupState.accounts.filter(a=>isDebt(a)!==debt);setupState.accounts=existing.concat(debt?[{id:'setup-card',name:'我的信用卡',ja:'マイカード',type:'credit',currency:'JPY',balance:92000,onceBalance:30000,splitBalance:50000,revoBalance:12000,next:32000,date:'2026-10-26',bank:'setup-jpy',confirmed:true},{id:'setup-loan',name:'人民币借款',ja:'人民元ローン',type:'loan',currency:'CNY',loanMode:'fixed',balance:18000,next:8500,date:'2026-10-25',bank:'setup-cny',confirmed:true}]:[{id:'setup-jpy',name:'日元生活账户',ja:'円生活口座',type:'bank',currency:'JPY',balance:48000},{id:'setup-cny',name:'人民币账户',ja:'人民元口座',type:'bank',currency:'CNY',balance:6800}]);render();return true;}
 if(name==='setup-finish'){const n=seedBook(uid('book'),setupState.name,Number(setupState.budget)||0);Object.assign(n,{ja:setupState.name,baseCurrency:setupState.base,categories:[],incomeCategories:[],records:[],activities:[],friends:[],treats:[],recurring:[],expected:[],sources:[],matches:[],accounts:setupState.accounts.map(a=>({...a})),theme:book().theme,language:book().language,startDate:setupState.date,analysisPrefs:null});books.push(n);currentBook=n.id;closeSheet();navigate('home');toast(t('新账本已建立，期初不计收入或消费','新規帳簿を作成。期首は収入・支出に含めません'));return true;}
 if(name==='exchange-open'){startExchange({from:el.dataset.from,to:el.dataset.to});return true;}
 if(name==='entry'&&el.dataset.type==='transfer'){startExchange({from:el.dataset.account});return true;}
 if(name==='capture-kind'&&el.dataset.kind==='transfer'){captureFields();startExchange();return true;}
 if(name==='capture-edit'&&book().records.find(r=>r.id===id)?.type==='transfer'){startExchange({edit:id});return true;}
 if(name==='entry'&&(!el.dataset.type||el.dataset.type==='expense'||el.dataset.type==='income')){beginCategorySelection({type:el.dataset.type||'expense',account:el.dataset.account,amount:el.dataset.amount,date:el.dataset.date,activity:el.dataset.activity??(pageName==='activity'?pageId:book().activeActivity)});return true;}
 if(name==='foreign-estimate'){captureFields();const f=captureSession.fields;f.amount=demoConvert(Number(f.originalAmount),f.originalCurrency,accountCurrency(f.account));f.settlementState='pending';renderEntry();return true;}
 if(name==='exchange-estimate'){captureFields();const n=exchangeMath();captureSession.fields.inAmount=estimatedExchangeIn();renderExchange();return true;}
 if(name==='activity-settings'||name==='edit-activity'||name==='new-activity'){editActivity(id);return true;}
 if(name==='activity-add-friend'){stashActivity();openSheet(t('添加同行朋友','同行者を追加'),`<form id="activity-friend-form">${field('name',t('朋友名字','友人の名前'),'text','','required')}<button class="full-button" type="submit">${t('添加到这个活动','このシーンに追加')}</button></form>`);return true;}
 if(name==='treat-me'||name==='treat-other'){const a=book().activities.find(a=>a.id===(el.dataset.activity|| (pageName==='activity'?pageId:book().activeActivity)));if(!a){openSheet(t('先选择一个活动','まずシーンを選択'),`<p class="muted">${t('互请只在活动内记录，不创建长期往来。','ごちそうはシーン内のみ。長期の関係帳は作りません。')}</p>${book().activities.map(a=>pageButton('activity',esc(label(a)),a.id,'list-button')).join('')||empty(t('先创建活动','先にシーンを作成'),'new-activity',t('创建活动','シーンを作成'))}`);}else if(name==='treat-other')treatOther(el.dataset.friend,a.id);else{entryType='expense';entry({activity:a.id,friend:el.dataset.friend,category:book().categories[0]?.id,date:a.end<TODAY?a.end:TODAY});}return true;}
 if(name==='analysis-preview'){analysisPreview=true;render();return true;}
 if(name==='analysis-clear-preview'){analysisPreview=false;render();return true;}
 if(name==='analysis-add-focus'){analysisDraft=[id];pageName='analysis-custom';pageId='';render();window.scrollTo(0,0);return true;}
 if(name==='analysis-use-example'){analysisDraft=['categories','merchants','trend'];render();return true;}
 if(name==='analysis-move'){const index=analysisDraft.indexOf(id),next=index+Number(el.dataset.direction);[analysisDraft[index],analysisDraft[next]]=[analysisDraft[next],analysisDraft[index]];render();return true;}
 if(name==='analysis-apply'){book().analysisPrefs={order:[...analysisDraft]};analysisPreview=false;analysisTab='spend';navigate('analysis');toast(t('已按当前账本保存分析偏好','この帳簿の分析設定を保存'));return true;}
 if(name==='fx-confirm-preview'){fxConfirmPreview(id);return true;}
 if(name==='fx-confirm-save'){const r=book().records.find(r=>r.id===id);balanceChange(r,true);r.originalEstimate=r.accountAmount??r.amount;r.amount=15230;r.accountAmount=15230;r.settlementState='confirmed';balanceChange(r);closeSheet();render();toast(t('原条目入账金额已确认，未新增消费','元の計上額を確認。新規支出はありません'));return true;}
 if(name==='fx-keep-difference'){book().records.find(r=>r.id===id).differenceConfirmed=true;closeSheet();render();toast(t('已确认差异，原记录仍为预计金额','差額を確認。元の金額は見込みのまま'));return true;}
 if(name==='loan-rules'){loanRuleEditor(id);return true;}
 if(name==='select-option'){
 const input=el.closest('.custom-select')?.querySelector('input'),fieldName=input?.name;
 if(document.getElementById('entry-form')&&captureSession?.context.flow!=='exchange'&&fieldName==='account'){const oldCurrency=accountCurrency(input.value),newCurrency=accountCurrency(el.dataset.value);queueMicrotask(()=>{captureFields();if(oldCurrency!==newCurrency){const f=captureSession.fields;if(!f.originalCurrency){f.originalCurrency=oldCurrency;f.originalAmount=f.amount;}f.amount=demoConvert(Number(f.amount),oldCurrency,newCurrency);f.settlementState='pending';}const scroll=document.querySelector('.sheet').scrollTop;renderEntry();document.querySelector('.sheet').scrollTop=scroll;});return false;}
 if(document.getElementById('experience-account-form')&&['type','currency','loanMode'].includes(fieldName)){queueMicrotask(()=>{stashAccount();renderAccountEditor();});return false;}
 if(document.getElementById('setup-book-form')&&fieldName==='base'){queueMicrotask(()=>{stashSetupBook();render();});return false;}
 if(captureSession?.context.flow==='exchange'&&document.getElementById('entry-form')&&['account','to','feePosition','feeCurrency','transferState'].includes(fieldName)){queueMicrotask(()=>{captureFields();if(['account','to'].includes(fieldName)){const n=exchangeMath();captureSession.fields.inAmount=estimatedExchangeIn();}const scroll=document.querySelector('.sheet').scrollTop;renderExchange();document.querySelector('.sheet').scrollTop=scroll;});return false;}
 if(document.getElementById('treat-form')&&fieldName==='payer'){queueMicrotask(()=>refreshAllocations());return false;}
 }
 return false;
}
function stashSetupBook(){const f=document.getElementById('setup-book-form');if(f)Object.assign(setupState,Object.fromEntries(new FormData(f)));}
function experienceSubmit(form){const fd=new FormData(form),get=name=>fd.get(name),number=name=>Number(get(name))||0;
 if(form.id==='setup-book-form'){stashSetupBook();setupState.step=2;render();window.scrollTo(0,0);return true;}
 if(form.id==='experience-account-form'){stashAccount();const d=accountDraft,a={...d.values,id:d.id||uid('account'),ja:d.values.name,balance:Number(d.values.balance)||0,next:Number(d.values.next)||0,limit:Number(d.values.limit)||0,confirmed:!!Number(d.values.next)};const list=d.setup?setupState.accounts:book().accounts;const old=list.find(x=>x.id===a.id);if(old)Object.assign(old,a);else list.push(a);closeSheet();render();toast(t('账户与期初信息已保存','口座・期首情報を保存'));return true;}
 if(form.id==='experience-activity-form'){stashActivity();const d=activityDraft,a={...d.values,id:d.id||uid('activity'),ja:d.values.name,budget:Number(d.values.budget)||0,holdAmount:Number(d.values.holdAmount)||0};const old=book().activities.find(x=>x.id===a.id);if(old)Object.assign(old,a);else book().activities.push(a);closeSheet();navigate('activity',a.id);return true;}
 if(form.id==='activity-friend-form'){const id=uid('friend'),name=get('name');book().friends.push({id,name,ja:name});activityDraft.values.friends.push(id);renderActivityEditor();return true;}
 if(form.id==='treat-form'){const a=book().activities.find(a=>a.id===get('activity')),payer=get('payer'),participants=[...new Set(['me',payer,...fd.getAll('friends')])],alloc=Object.fromEntries(participants.map(id=>[id,number(`alloc-${id}`)]));if(Math.abs(sum(Object.values(alloc),n=>n)-number('amount'))>.01){toast(t('实际份额合计需等于整单金额','配分合計を総額と同じに'));return true;}if(get('date')<a.start||get('date')>a.end){toast(t('互请日期需在活动期间内，可先调整活动日期','利用日はシーン期間内に。期間変更も可能です'));return true;}book().treats.push({id:uid('treat'),activity:a.id,payer,alloc,amount:number('amount'),merchant:get('merchant'),date:get('date')});closeSheet();navigate('activity',a.id);toast(t('只保存本活动往来，未改变你的资金或消费','シーン内のみ保存。自分の残高・支出は未変更'));return true;}
 if(form.id==='loan-rule-form'){account(form.dataset.id).loanRules=Object.fromEntries(fd);closeSheet();render();toast(t('规则信息已保存，计算仅为正式应用规格','条件情報を保存。計算は正式アプリの仕様'));return true;}
 if(form.id==='entry-form'&&captureSession?.context.flow==='exchange'){captureFields();const s=captureSession,f=s.fields,from=account(f.account),to=account(f.to);if(!from||!to||from.id===to.id){toast(t('请选择不同的转出与转入账户','異なる出金・入金口座を選択'));return true;}const old=s.context.edit?book().records.find(r=>r.id===s.context.edit):null;const r={...(old||{}),id:old?.id||uid('transfer'),type:'transfer',amount:demoConvert(Number(f.amount),from.currency,bookCurrency()),accountAmount:Number(f.amount),currency:from.currency,account:from.id,to:to.id,toAmount:Number(f.inAmount),date:f.date,arrivalDate:f.arrivalDate,transferState:f.transferState,exchangeFee:f.fee===''?null:Number(f.fee),feeCurrency:f.feeCurrency,feePosition:f.feePosition,merchant:f.merchant,note:f.note,attachments:s.attachments,receipts:s.receipts,activity:''};if(old){balanceChange(old,true);Object.assign(old,r);}else book().records.push(r);balanceChange(r);const oldFee=book().records.find(x=>x.transferFeeFor===r.id);if(oldFee){if(!oldFee.includedInTransfer)balanceChange(oldFee,true);book().records=book().records.filter(x=>x.id!==oldFee.id);}if(r.transferState!=='planned'&&r.exchangeFee>0){const feeAccount=r.feePosition==='to-included'?to:account(f.feeAccount)||from;const fee={id:oldFee?.id||uid('fee'),type:'expense',date:r.date,account:feeAccount.id,accountAmount:demoConvert(r.exchangeFee,r.feeCurrency,feeAccount.currency),currency:feeAccount.currency,amount:demoConvert(r.exchangeFee,r.feeCurrency,bookCurrency()),category:category('other')?'other':'',merchant:t('转账 / 换汇手续费','振替・両替手数料'),payment:'fee',activity:'',transferFeeFor:r.id,includedInTransfer:r.feePosition!=='extra'};book().records.push(fee);if(!fee.includedInTransfer)balanceChange(fee);}closeSheet();render();recordDetail(r.id);toast(t('已按两端实际金额记录，转账本金不计消费','両側の実額で記録。元金は支出に含めません'));return true;}
 if(form.id==='entry-form'){captureFields();const f=captureSession.fields;if(f.friends?.length&&f.activity){const a=book().activities.find(a=>a.id===f.activity);if(f.date<a.start||f.date>a.end){toast(t('互请日期需在活动期间内，可先调整活动日期','利用日はシーン期間内に。期間変更も可能です'));return true;}}}
 return false;
}
refreshAllocations=(preserve=false)=>{const form=document.getElementById('entry-form')||document.getElementById('treat-form');if(!form)return;const total=Number(form.elements.amount.value)||0;if(form.id==='treat-form'){const payer=form.elements.payer.value;form.querySelectorAll('input[name="friends"]').forEach(input=>{input.closest('label').hidden=input.value===payer;if(input.value===payer)input.checked=false;});}const selected=[...form.querySelectorAll('input[name="friends"]:checked')].map(x=>x.value);let ids=form.id==='treat-form'?[...new Set(['me',form.elements.payer.value,...selected])]:selected.length?['me',...selected]:[];const target=form.querySelector('#allocations');if(!target)return;const currency=form.id==='entry-form'?accountCurrency(form.elements.account.value):bookCurrency(),factor=currency==='JPY'?1:100,minor=Math.round(total*factor),part=Math.floor(minor/(ids.length||1));target.innerHTML=ids.map((id,i)=>field(`alloc-${id}`,`${id==='me'?t('我自己的份额','自分の分'):esc(label(book().friends.find(f=>f.id===id)))} · ${currency}`,'number',preserve&&captureSession?.fields[`alloc-${id}`]!=null?captureSession.fields[`alloc-${id}`]:(part+(i===ids.length-1?minor-part*ids.length:0))/factor,`min="0" step="${currency==='JPY'?1:.01}"`)).join('')+(ids.length?`<p class="muted">${t('包含付款人和自己在内均分，实际份额合计等于整单。','支払者と自分を含め均等配分。合計は総額と同じに。')}</p>`:'');};
document.addEventListener('input',e=>{if(e.target.closest('#setup-book-form'))stashSetupBook();if(e.target.closest('#entry-form')&&captureSession?.context.flow==='exchange'){captureFields();const target=document.getElementById('exchange-rate-note');if(target)target.innerHTML=exchangeRateNote();}});
document.addEventListener('change',e=>{if(e.target.dataset.analysisModule){const id=e.target.dataset.analysisModule;if(e.target.checked)analysisDraft.push(id);else analysisDraft=analysisDraft.filter(x=>x!==id);render();}if(e.target.closest('#experience-activity-form')&&['excludeMonthly','holdEnabled'].includes(e.target.name)){stashActivity();const scroll=document.querySelector('.sheet').scrollTop;renderActivityEditor();document.querySelector('.sheet').scrollTop=scroll;}});
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.type!=='yohaku-preview')return;const p=e.data.page;if(p==='exchange-demo'){startExchange();}else if(p==='activity-demo'||p==='friends'){const a=book().activities[0];if(a)navigate('activity',a.id);else navigate('life');}else if(p==='foreign-entry'){entryType='expense';entry({category:'shopping',account:'pp',amount:15000,originalCurrency:'USD',originalAmount:100,settlementState:'pending'});}else if(p==='onboarding'){setupState={step:0,name:'',base:bookCurrency(),budget:'',date:TODAY,accounts:[]};navigate('onboarding');}else if(p==='analysis-custom'){analysisDraft=[...(book().analysisPrefs?.order||[])];render();}});
function currencyContextForPage(){if(['credit','loan','bank','rules'].includes(pageName))return accountCurrency(pageId);if(pageName==='reconcile'){const source=book().sources.find(s=>s.id===pageId)||book().sources.at(-1);if(source)return accountCurrency(source.account);}return bookCurrency();}
function receiptExpectedAmount(r,currency){if(currency===r.originalCurrency)return Number(r.originalAmount);if(currency===(r.currency||accountCurrency(r.account)))return Number(r.accountAmount??r.amount);if(currency===bookCurrency())return Number(r.amount);return null;}
function recordTransferSummary(r){if(r.type==='repayment')return `<div class="record-fx-recap">${rows([[t('实际付款','実際の支払'),`<span class="recap-money">${recordMainMoney(r)}</span>`],[t('偿还账户','返済口座'),esc(label(account(r.to)))],[t('归还本金','元金返済'),`<span class="recap-money">${moneyIn(r.principal,accountCurrency(r.to))}</span>`],[t('其中利息 / 费用','うち利息・費用'),`<span class="recap-money">${moneyIn(r.repaymentFee||0,r.currency)}</span>`]])}</div>`;if(r.type!=='transfer')return '';const state={confirmed:t('已到账','入金済'),inTransit:t('在途，收款余额尚未增加','送金中・入金残高は未加算'),planned:t('计划，未改变实际余额','予定・実残高は未変更')}[r.transferState||'confirmed'];return `<div class="record-fx-recap">${rows([[t('实际转出','実際の出金'),`<span class="recap-money">${recordMainMoney(r)}</span>`],[t('实际转入','実際の入金'),`<span class="recap-money">${moneyIn(r.toAmount??r.accountAmount??r.amount,accountCurrency(r.to))}</span>`],[t('转入账户','入金口座'),esc(label(account(r.to)))],[t('手续费','手数料'),r.exchangeFee==null?t('未填写，不从汇差猜测','未入力・換算差から推定しない'):`<span class="recap-money">${moneyIn(r.exchangeFee,r.feeCurrency)}</span>`],[t('资金状态','資金の状態'),state],[t('到账日期','入金日'),r.arrivalDate||r.date]])}</div>`;}
render();
